    #[inline]
    pub fn len(xs: SynsA) -> Int {
        if null_p(xs) {
            int_lit(0)
        } else {
            _plus(int_lit(1), len(cdr(xs)))
        }
    }

    pub fn nth(mut xs: SynsA, mut i: Int) -> kayak_rt::Handle<'static, Syn> {
        loop {
            if _eq(i, int_lit(0)) {
                return car(xs);
            } else {
                (xs, i) = (cdr(xs), _minus(i, int_lit(1)));
                continue;
            }
        }
    }

    pub fn drop(mut xs: SynsA, mut i: Int) -> SynsA {
        loop {
            if _eq(i, int_lit(0)) {
                return xs;
            } else {
                (xs, i) = (cdr(xs), _minus(i, int_lit(1)));
                continue;
            }
        }
    }

    #[inline]
    pub fn mk_symbol(n: Str, a: Int, b: Int) -> kayak_rt::Handle<'static, Syn> {
        atom(kayak_rt::value::ToValue::to_value(string_to_symbol(n)), a, b, int_lit(0))
    }

    #[inline]
    pub fn syn_datums(xs: SynsA) -> List<kayak_rt::value::Value> {
        if null_p(xs) {
            nil::<kayak_rt::value::Value>()
        } else {
            kayak_rt::heap_cons(syn_to_datum(car(xs)), syn_datums(cdr(xs)))
        }
    }

