    pub fn split(s: kayak_rt::Handle<'static, Syn>) -> SynsA {
        let tagcase_ = s;
        match *tagcase_ {
            made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                if null_p(items) {
                    nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
                } else {
                    kayak_rt::heap_cons(car(items), kayak_rt::heap_cons(if null_p(cdr(items)) {
                        atom(kayak_rt::value::Value::Nil, a, b, x)
                    } else {
                        mx_eager_reader_types_lst(cdr(items), if kayak_rt::value::pair_p(d) {
                            kayak_rt::value::cdr(d)
                        } else {
                            d
                        }, a, b, x)
                    }, kayak_rt::nil()))
                }
            }
            made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                kayak_rt::heap_cons(car(items), kayak_rt::heap_cons(if null_p(cdr(items)) {
                    tail
                } else {
                    dotted(cdr(items), tail, if kayak_rt::value::pair_p(d) {
                        kayak_rt::value::cdr(d)
                    } else {
                        d
                    }, a, b, x)
                }, kayak_rt::nil()))
            }
            _ => {
                let y = tagcase_;
                nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
            }
        }
    }

    pub fn datum_to_syn(d: kayak_rt::value::Value) -> kayak_rt::Handle<'static, Syn> {
        if kayak_rt::value::pair_p(d) {
            let parts = datum_parts(d);
            if null_p(cdr(parts)) {
                mx_eager_reader_types_lst(car(parts), d, int_lit(0), int_lit(0), int_lit(0))
            } else {
                dotted(car(parts), car(car(cdr(parts))), d, int_lit(0), int_lit(0), int_lit(0))
            }
        } else {
            atom(d, int_lit(0), int_lit(0), int_lit(0))
        }
    }

    pub fn datum_parts(d: kayak_rt::value::Value) -> List<SynsA> {
        let go__knot = knot::<kayak_rt::Proc1s<'static, kayak_rt::value::Value, SynsA>>();
        let end__knot = knot::<kayak_rt::Proc1s<'static, kayak_rt::value::Value, kayak_rt::value::Value>>();
        let go = kayak_rt::as_proc(kayak_rt::closure1s((go__knot,), |(go__knot,), x: kayak_rt::value::Value| {
            if kayak_rt::value::pair_p(x) {
                kayak_rt::heap_cons(datum_to_syn(kayak_rt::value::car(x)), (go__knot.get()).call(kayak_rt::value::cdr(x)))
            } else {
                nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
            }
        }));
        let end = kayak_rt::as_proc(kayak_rt::closure1s((), |(), mut x: kayak_rt::value::Value| {
            loop {
                if kayak_rt::value::pair_p(x) {
                    x = kayak_rt::value::cdr(x);
                    continue;
                } else {
                    return x;
                }
            }
        }));
        go__knot.set(go);
        end__knot.set(end);
        let e = end.call(d);
        if kayak_rt::value::null_p(e) {
            kayak_rt::heap_cons(go.call(d), kayak_rt::nil())
        } else {
            kayak_rt::heap_cons(go.call(d), kayak_rt::heap_cons(the::<SynsA>(kayak_rt::heap_cons(atom(e, int_lit(0), int_lit(0), int_lit(0)), kayak_rt::nil())), kayak_rt::nil()))
        }
    }

    pub fn show_datum(d: kayak_rt::value::Value) -> Str {
        if kayak_rt::value::null_p(d) {
            str_lit("()")
        } else if symbol_p(d) {
            symbol_to_string(kayak_rt::value::unbox::<Symbol>(d))
        } else if mx_keyword_p(d) {
            string_append(str_lit("#:"), symbol_to_string(mx_keyword_to_symbol(d)))
        } else if string_p(d) {
            string_append(str_lit("\""), string_append(kayak_rt::value::unbox::<Str>(d), str_lit("\"")))
        } else if char_p(d) {
            string_append(str_lit("#\\"), char_to_string(kayak_rt::value::unbox::<char>(d)))
        } else if int_p(d) {
            int_to_string(kayak_rt::value::unbox::<Int>(d))
        } else if f64_p(d) {
            f64_to_string(kayak_rt::value::unbox::<f64>(d))
        } else if bool_p(d) {
            if kayak_rt::value::unbox::<bool>(d) {
                str_lit("#t")
            } else {
                str_lit("#f")
            }
        } else {
            str_lit("…")
        }
    }

    pub fn show_syn(s: kayak_rt::Handle<'static, Syn>) -> Str {
        let tagcase_ = s;
        match *tagcase_ {
            made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                if null_p(items) {
                    str_lit("()")
                } else {
                    string_append(str_lit("("), string_append(mx_syntax_show_each(items), str_lit(")")))
                }
            }
            made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                string_append(str_lit("("), string_append(mx_syntax_show_each(items), string_append(str_lit(" . "), string_append(show_syn(tail), str_lit(")")))))
            }
            made__load__2__expander::Syn::Vec(items, d, a, b, x) => {
                string_append(str_lit("#("), string_append(mx_syntax_show_each(items), str_lit(")")))
            }
            made__load__2__expander::Syn::Atom(d, a, b, x) => {
                show_datum(d)
            }
        }
    }

    pub fn mx_syntax_show_each(xs: SynsA) -> Str {
        if null_p(xs) {
            str_lit("")
        } else if null_p(cdr(xs)) {
            show_syn(car(xs))
        } else {
            string_append(show_syn(car(xs)), string_append(str_lit(" "), mx_syntax_show_each(cdr(xs))))
        }
    }

