    pub fn atms_onto(mut xs: Atms, mut r#as: Atms) -> Atms {
        loop {
            if null_p(xs) {
                return r#as;
            } else if atm_in_p(car(xs), r#as) {
                xs = cdr(xs);
                continue;
            } else {
                (xs, r#as) = (cdr(xs), kayak_rt::heap_cons(car(xs), r#as));
                continue;
            }
        }
    }

    pub fn exports_onto(mut ls: Levels, mut r#as: Atms, mut ns: MxParserTypesNames) -> MxExportsExported {
        loop {
            if null_p(ls) {
                return Product_11_12(r#as, ns);
            } else {
                let tagcase_ = car(ls);
                match *tagcase_ {
                    made__load__2__expander::Level::LvRib(xs) => {
                        (ls, r#as) = (cdr(ls), atms_onto(xs, r#as));
                        continue;
                    }
                    made__load__2__expander::Level::LvEarlier(xs) => {
                        (ls, r#as) = (cdr(ls), atms_onto(xs, r#as));
                        continue;
                    }
                    made__load__2__expander::Level::LvCage(n) => {
                        (ls, ns) = (cdr(ls), if mx_syntax_name_in_p(n, ns) {
                            ns
                        } else {
                            kayak_rt::heap_cons(n, ns)
                        });
                        continue;
                    }
                    made__load__2__expander::Level::LvShape(m) => {
                        ls = cdr(ls);
                        continue;
                    }
                }
            }
        }
    }

