    pub fn binders_under<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut at: Int, mut m: Symbol) -> Nested {
        loop {
            let tagcase_ = node_kids(mxp, maker_st, at);
            match *tagcase_ {
                made__load__2__expander::MxNodesKids::KPair(x, y) => {
                    return append(binders_under(mxp, maker_st, x, m), binders_under(mxp, maker_st, y, m));
                }
                made__load__2__expander::MxNodesKids::KForm(x) => {
                    at = x;
                    continue;
                }
                made__load__2__expander::MxNodesKids::MxNodesKSeq(x) => {
                    at = x;
                    continue;
                }
                made__load__2__expander::MxNodesKids::KDesc(xs) => {
                    return binders_under_each(mxp, maker_st, xs, m);
                }
                made__load__2__expander::MxNodesKids::KBinder(n, d) => {
                    if d {
                        return the::<Nested>(nil::<Product_11_12<Symbol, Symbol>>());
                    } else {
                        return the::<Nested>(kayak_rt::cons(Product_11_12(n, m), kayak_rt::nil()));
                    }
                }
                _ => {
                    let y = tagcase_;
                    return the::<Nested>(nil::<Product_11_12<Symbol, Symbol>>());
                }
            }
        }
    }

    #[inline]
    pub fn binders_under_each<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, xs: List<Int>, m: Symbol) -> Nested {
        if null_p(xs) {
            nil::<Product_11_12<Symbol, Symbol>>()
        } else {
            append(binders_under(mxp, maker_st, car(xs), m), binders_under_each(mxp, maker_st, cdr(xs), m))
        }
    }

    pub fn nested_from<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut i: Int, mut j: Int, mut ps: Pvars, mut out: Nested) -> Result<Nested, Unwind> {
        loop {
            if _lt(j, i) {
                return Ok(out);
            } else {
                let items = proper_items(node_syn(mxp, maker_st, j));
                let h = if (not(null_p(items)) && syn_symbol_p(car(items))) {
                    kayak_rt::cons(car(items), kayak_rt::nil())
                } else {
                    nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
                };
                let here = {
                    let tagcase_ = node_kids(mxp, maker_st, j);
                    match *tagcase_ {
                        made__load__2__expander::MxNodesKids::KForm(x) => {
                            if (not(null_p(h)) && not(pvar_p(syn_symbol(mxp, maker_st, car(h))?, ps)) && makes_defns_p(mxp, maker_st, syn_symbol(mxp, maker_st, car(h))?)) {
                                binders_under(mxp, maker_st, x, syn_symbol(mxp, maker_st, car(h))?)
                            } else {
                                nil::<Product_11_12<Symbol, Symbol>>()
                            }
                        }
                        _ => {
                            let y = tagcase_;
                            nil::<Product_11_12<Symbol, Symbol>>()
                        }
                    }
                };
                (j, out) = (_minus(j, int_lit(1)), append(here, out));
                continue;
            }
        }
    }

