    pub fn made_said(k: Int) -> Str {
        if _eq(k, int_lit(1)) {
            str_lit("definitions")
        } else if _eq(k, int_lit(2)) {
            str_lit("a description")
        } else {
            str_lit("an expression")
        }
    }

