    pub fn nth_of(mut j: Int, mut xs: List<Product_11_12<Str, bool>>) -> Product_11_12<Str, bool> {
        loop {
            if _eq(j, int_lit(0)) {
                return car(xs);
            } else {
                (j, xs) = (_minus(j, int_lit(1)), cdr(xs));
                continue;
            }
        }
    }

