    pub fn mx_solve_solve<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, ps: ByClause, prev: Sol, makes: MxInferInts, of: MxInferInts) -> Sol {
        let pk = keep_failed(ps, prev.1, pkinds_each(mxp, maker_st, ps, int_lit(0), nil::<Product_11_12_13<Int, Symbol, kayak_rt::Handle<'static, made__load__2__expander::Kd>>>()));
        let ks = part_kinds(mxp, maker_st, get(maker_st.found_vars.get().unwrap()), pk, nil::<Int>());
        let kinds = ks.0;
        let sticky = ks.1;
        let many = many_each(mxp, maker_st, ps, int_lit(0), kinds, nil::<Int>());
        set(maker_st.demands.get().unwrap(), nil::<Product_11_12<Int, kayak_rt::Handle<'static, made__load__2__expander::Demand>>>());
        let sites = sites_each(mxp, maker_st, ps, int_lit(0), kinds, nil::<Product_11_12<Int, List<Product_11_12<Int, List<kayak_rt::Handle<'static, made__load__2__expander::Rd>>>>>>());
        let imports = imports_each(mxp, maker_st, sorted_sites(sites, nil::<Product_11_12<Int, List<Product_11_12<Int, List<kayak_rt::Handle<'static, made__load__2__expander::Rd>>>>>>()));
        let roots_ex = root_exports(mxp, maker_st, get(maker_st.mx_infer_roots.get().unwrap()), int_lit(0), makes, of, ps);
        let exports = exports_of_demands(mxp, maker_st);
        Product_11_12_13_14_15_16_17(kinds, pk, many, imports, exports, roots_ex, sticky)
    }

    pub fn mx_solve_head_is_p(s: kayak_rt::Handle<'static, Syn>, h: Str) -> bool {
        let ps = proper_items(s);
        (pair_p(ps) && syn_symbol_p(car(ps)) && string_eq_p(syn_name(car(ps)), h))
    }

    pub fn defn_arrow(s: kayak_rt::Handle<'static, Syn>, a: Int, b: Int) -> kayak_rt::Handle<'static, Syn> {
        let ps = proper_items(s);
        let rho = if (_eq(len(ps), int_lit(3)) && mx_solve_head_is_p(s, str_lit("export")) && mx_solve_head_is_p(nth(ps, int_lit(2)), str_lit("rho"))) {
            proper_items(nth(ps, int_lit(2)))
        } else {
            nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
        };
        if null_p(rho) {
            mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("macro/addressed"), a, b), kayak_rt::heap_cons(s, kayak_rt::heap_cons(mk_symbol(str_lit("defn"), a, b), kayak_rt::nil()))), a, b)
        } else {
            let made = mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("defn"), a, b), cdr(rho)), a, b);
            mk_list(kayak_rt::heap_cons(mk_symbol(str_lit("macro/addressed"), a, b), kayak_rt::heap_cons(nth(ps, int_lit(1)), kayak_rt::heap_cons(made, kayak_rt::nil()))), a, b)
        }
    }

    pub fn made_sigs<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, sigs: SynsA, makes: MxInferInts, us: Unsigneds) -> SynsA {
        if null_p(sigs) {
            nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
        } else {
            let u = car(us);
            let a = syn_start(u.3);
            let b = syn_end(u.3);
            cons(if _eq(car(makes), int_lit(1)) {
                defn_arrow(car(sigs), a, b)
            } else {
                mk_list(kayak_rt::cons(mk_symbol(str_lit("macro/addressed"), a, b), kayak_rt::cons(car(sigs), kayak_rt::cons(mk_symbol(if _eq(car(makes), int_lit(0)) {
                    str_lit("expr")
                } else {
                    str_lit("desc")
                }, a, b), kayak_rt::nil()))), a, b)
            }, made_sigs(mxp, maker_st, cdr(sigs), cdr(makes), cdr(us)))
        }
    }

