    pub fn syn_hash<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: kayak_rt::Handle<'static, Syn>) -> Int {
        let tagcase_ = s;
        match *tagcase_ {
            made__load__2__expander::Syn::Atom(d, a, b, x) => {
                if symbol_p(d) {
                    mix(mxp, maker_st, int_lit(1), text_hash(mxp, maker_st, symbol_to_string(kayak_rt::value::unbox::<Symbol>(d))))
                } else if string_p(d) {
                    mix(mxp, maker_st, int_lit(2), text_hash(mxp, maker_st, kayak_rt::value::unbox::<Str>(d)))
                } else if int_p(d) {
                    mix(mxp, maker_st, int_lit(7), modulo(kayak_rt::value::unbox::<Int>(d), maker_st.hash_p.get().unwrap()))
                } else if f64_p(d) {
                    mix(mxp, maker_st, int_lit(8), text_hash(mxp, maker_st, f64_to_string(kayak_rt::value::unbox::<f64>(d))))
                } else if char_p(d) {
                    mix(mxp, maker_st, int_lit(9), char_to_integer(kayak_rt::value::unbox::<char>(d)))
                } else if bool_p(d) {
                    mix(mxp, maker_st, int_lit(10), if kayak_rt::value::unbox::<bool>(d) {
                        int_lit(1)
                    } else {
                        int_lit(0)
                    })
                } else if mx_keyword_p(d) {
                    mix(mxp, maker_st, int_lit(11), text_hash(mxp, maker_st, symbol_to_string(mx_keyword_to_symbol(d))))
                } else {
                    int_lit(3)
                }
            }
            made__load__2__expander::Syn::MxEagerReaderTypesLst(xs, d, a, b, x) => {
                syns_hash(mxp, maker_st, int_lit(4), xs)
            }
            made__load__2__expander::Syn::Dotted(xs, t, d, a, b, x) => {
                mix(mxp, maker_st, syns_hash(mxp, maker_st, int_lit(5), xs), syn_hash(mxp, maker_st, t))
            }
            made__load__2__expander::Syn::Vec(xs, d, a, b, x) => {
                syns_hash(mxp, maker_st, int_lit(6), xs)
            }
        }
    }

    pub fn syns_hash<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut h: Int, mut xs: SynsA) -> Int {
        loop {
            if null_p(xs) {
                return h;
            } else {
                (h, xs) = (mix(mxp, maker_st, h, syn_hash(mxp, maker_st, car(xs))), cdr(xs));
                continue;
            }
        }
    }

