    pub fn scope_renames(mut in_scope: List<Symbol>, mut bs: MxContractsNumbered, mut fs: MxContractsNumbered, mut out: MxContractsRenames) -> MxContractsRenames {
        loop {
            if null_p(in_scope) {
                return out;
            } else {
                let k = mx_contracts_var_part(car(in_scope));
                let x = part_name(k, bs);
                let to = part_name(k, fs);
                (in_scope, out) = (cdr(in_scope), if (null_p(x) || not(null_p(renamed_to(car(x), out)))) {
                    out
                } else {
                    kayak_rt::heap_cons(Product_11_12(car(x), car(to)), out)
                });
                continue;
            }
        }
    }

    pub fn part_renames(mut vs: List<PartVar>, mut parts: SynsA, mut bs: MxContractsNumbered, mut fs: MxContractsNumbered, mut out: Renamings) -> Renamings {
        loop {
            if null_p(vs) {
                return out;
            } else {
                let k = car(vs).0;
                let own = if car(vs).1 {
                    the::<MxContractsRenames>(kayak_rt::heap_cons(Product_11_12(car(part_name(k, bs)), car(part_name(k, fs))), kayak_rt::nil()))
                } else {
                    nil::<Product_11_12<Symbol, Symbol>>()
                };
                let rs = scope_renames(car(vs).2, bs, fs, own);
                let p = nth(parts, k);
                (vs, out) = (cdr(vs), if null_p(rs) {
                    out
                } else {
                    kayak_rt::heap_cons(Product_11_12_13_14(syn_start(p), syn_end(p), rs, car(vs).3), out)
                });
                continue;
            }
        }
    }

    pub fn contract_renames<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, sig: kayak_rt::Handle<'static, Sty>, operands: kayak_rt::Handle<'static, Syn>) -> Result<Product_11_12<Renamings, MxContractsRenames>, Unwind> {
        let leaves = leaves_of(mxp, maker_st, mx_fail, int_lit(0), get(maker_st.nnodes.get().unwrap()), nil::<Product_11_12<Int, Int>>())?;
        let made = {
            set(maker_st.pseudo_parts.get().unwrap(), nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>());
            pseudo_pattern(mxp, maker_st, operands, leaves)
        };
        let parts = the::<SynsA>(reverse(get(maker_st.pseudo_parts.get().unwrap())));
        let root = {
            nodes_reset_x(mxp, maker_st);
            align(mxp, maker_st, mx_fail, int_lit(0), the::<Pvars>(nil::<Product_11_12<Symbol, Product_11_12_13_14_15<kayak_rt::Handle<'static, made__load__2__expander::Sty>, List<kayak_rt::Handle<'static, made__load__2__expander::Level>>, bool, List<Product_11_12<List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>, List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>>>, Int>>>()), sig, made, int_lit(-1), nil::<bool>())?
        };
        let mx_nodes_found = mx_scopes_walk(mxp, maker_st, mx_fail, root, maker_st.env_empty.get().unwrap(), false, int_lit(0))?;
        let vars = part_vars(mxp, maker_st, mx_fail, mx_nodes_found, parts, nil::<Product_11_12_13_14<Int, bool, List<Symbol>, kayak_rt::Handle<'static, made__load__2__expander::Sty>>>())?;
        let binders = binder_parts(mxp, maker_st, vars, parts, nil::<Product_11_12<Int, Symbol>>())?;
        let fresh = fresh_names(binders);
        Ok(Product_11_12(part_renames(vars, parts, binders, fresh, nil::<Product_11_12_13_14<Int, Int, List<Product_11_12<Symbol, Symbol>>, kayak_rt::Handle<'static, made__load__2__expander::Sty>>>()), the::<MxContractsRenames>(fresh_originals(binders, fresh))))
    }

    pub fn syn_renamed<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: kayak_rt::Handle<'static, Syn>, rs: MxContractsRenames) -> Result<kayak_rt::Handle<'static, Syn>, Unwind> {
        let tagcase_ = s;
        match *tagcase_ {
            made__load__2__expander::Syn::Atom(d, a, b, x) => {
                if syn_symbol_p(s) {
                    let to = renamed_to(syn_symbol(mxp, maker_st, s)?, rs);
                    if null_p(to) {
                        Ok(s)
                    } else {
                        Ok(atom(kayak_rt::value::ToValue::to_value(car(to)), a, b, x))
                    }
                } else {
                    Ok(s)
                }
            }
            made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                let xs = renamed_each(mxp, maker_st, items, rs)?;
                Ok(mx_eager_reader_types_lst(xs, kayak_rt::value::list(syn_datums(xs)), a, b, x))
            }
            made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                let (xs, tl) = (renamed_each(mxp, maker_st, items, rs)?, syn_renamed(mxp, maker_st, tail, rs)?);
                Ok(dotted(xs, tl, mx_datum_dotted(syn_datums(xs), syn_to_datum(tl)), a, b, x))
            }
            made__load__2__expander::Syn::Vec(items, d, a, b, x) => {
                let xs = renamed_each(mxp, maker_st, items, rs)?;
                Ok(vec(xs, datum_list_to_vector(kayak_rt::value::list(syn_datums(xs))), a, b, x))
            }
        }
    }

    #[inline]
    pub fn renamed_each<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, xs: SynsA, rs: MxContractsRenames) -> Result<SynsA, Unwind> {
        if null_p(xs) {
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            Ok(cons(syn_renamed(mxp, maker_st, car(xs), rs)?, renamed_each(mxp, maker_st, cdr(xs), rs)?))
        }
    }

