    pub fn syn_renamed_at(s: kayak_rt::Handle<'static, Syn>, at: PlacedRenames) -> kayak_rt::Handle<'static, Syn> {
        let tagcase_ = s;
        match *tagcase_ {
            made__load__2__expander::Syn::Atom(d, a, b, x) => {
                let to = placed_at(a, b, at);
                if (syn_symbol_p(s) && not(null_p(to))) {
                    atom(kayak_rt::value::ToValue::to_value(car(to)), a, b, x)
                } else {
                    s
                }
            }
            made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                let xs = renamed_at_each(items, at);
                mx_eager_reader_types_lst(xs, kayak_rt::value::list(syn_datums(xs)), a, b, x)
            }
            made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                let (xs, tl) = (renamed_at_each(items, at), syn_renamed_at(tail, at));
                dotted(xs, tl, mx_datum_dotted(syn_datums(xs), syn_to_datum(tl)), a, b, x)
            }
            made__load__2__expander::Syn::Vec(items, d, a, b, x) => {
                let xs = renamed_at_each(items, at);
                vec(xs, datum_list_to_vector(kayak_rt::value::list(syn_datums(xs))), a, b, x)
            }
        }
    }

    #[inline]
    pub fn renamed_at_each(xs: SynsA, at: PlacedRenames) -> SynsA {
        if null_p(xs) {
            nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
        } else {
            kayak_rt::heap_cons(syn_renamed_at(car(xs), at), renamed_at_each(cdr(xs), at))
        }
    }

    pub fn references_renamed<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, part: kayak_rt::Handle<'static, Syn>, core: kayak_rt::Handle<'static, Sty>, rs: MxContractsRenames) -> Result<kayak_rt::Handle<'static, Syn>, Unwind> {
        let mx_nodes_found = program_scoped(mxp, maker_st, mx_fail, core, part, false, nil::<Symbol>())?.1;
        let at = free_refs(mxp, maker_st, mx_nodes_found, rs, nil::<Product_11_12_13<Int, Int, Symbol>>());
        Ok(syn_renamed_at(part, at))
    }

    pub fn renamed_use<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, s: kayak_rt::Handle<'static, Syn>, ps: Renamings) -> Result<kayak_rt::Handle<'static, Syn>, Unwind> {
        let r = part_renames_at(syn_start(s), syn_end(s), ps);
        if not(null_p(r)) {
            let tagcase_ = car(r).1;
            match *tagcase_ {
                made__load__2__expander::Sty::SBvar() => {
                    Ok(syn_renamed(mxp, maker_st, s, car(r).0)?)
                }
                made__load__2__expander::Sty::SDvar() => {
                    Ok(syn_renamed(mxp, maker_st, s, car(r).0)?)
                }
                _ => {
                    let y = tagcase_;
                    Ok(references_renamed(mxp, maker_st, mx_fail, s, car(r).1, car(r).0)?)
                }
            }
        } else {
            let tagcase_ = s;
            match *tagcase_ {
                made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                    let xs = renamed_use_each(mxp, maker_st, mx_fail, items, ps)?;
                    Ok(mx_eager_reader_types_lst(xs, kayak_rt::value::list(syn_datums(xs)), a, b, x))
                }
                made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                    let (xs, tl) = (renamed_use_each(mxp, maker_st, mx_fail, items, ps)?, renamed_use(mxp, maker_st, mx_fail, tail, ps)?);
                    Ok(dotted(xs, tl, mx_datum_dotted(syn_datums(xs), syn_to_datum(tl)), a, b, x))
                }
                _ => {
                    let y = tagcase_;
                    Ok(s)
                }
            }
        }
    }

    pub fn renamed_use_each<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, xs: SynsA, ps: Renamings) -> Result<SynsA, Unwind> {
        if null_p(xs) {
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            Ok(cons(renamed_use(mxp, maker_st, mx_fail, car(xs), ps)?, renamed_use_each(mxp, maker_st, mx_fail, cdr(xs), ps)?))
        }
    }

    pub fn env_at<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut i: Int, mut fs: MxNodesFound) -> kayak_rt::Handle<'static, MxEnvIndexedEnv> {
        loop {
            if null_p(fs) {
                return maker_st.env_empty.get().unwrap();
            } else if _eq(i, car(fs).0) {
                return car(fs).1;
            } else {
                fs = cdr(fs);
                continue;
            }
        }
    }

    pub fn anode_of<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, i: Int, fs: MxNodesFound) -> Anode {
        let (none, no, bit) = (the::<List<Symbol>>(nil::<Symbol>()), the::<List<kayak_rt::Handle<'static, Syn>>>(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()), kayak_rt::closure1s((), |(), d: bool| {
            if d {
                int_lit(1)
            } else {
                int_lit(0)
            }
        }));
        let tagcase_ = node_kids(mxp, maker_st, i);
        match *tagcase_ {
            made__load__2__expander::MxNodesKids::KPair(x, y) => {
                Product_11_12_13_14(int_lit(0), kayak_rt::cons(x, kayak_rt::cons(y, kayak_rt::nil())), none, no)
            }
            made__load__2__expander::MxNodesKids::KNil() => {
                Product_11_12_13_14(int_lit(1), nil::<Int>(), none, no)
            }
            made__load__2__expander::MxNodesKids::KBinder(m, d) => {
                Product_11_12_13_14(int_lit(2), kayak_rt::cons(bit.call(d), kayak_rt::nil()), none, no)
            }
            made__load__2__expander::MxNodesKids::KRef(m, d, f) => {
                let b = bound_by(mxp, maker_st, env_levels(env_at(mxp, maker_st, i, fs)), m, d);
                if _eq(b, int_lit(-1)) {
                    Product_11_12_13_14(int_lit(4), kayak_rt::cons(bit.call(d), kayak_rt::nil()), kayak_rt::cons(m, kayak_rt::nil()), no)
                } else {
                    Product_11_12_13_14(int_lit(3), kayak_rt::cons(b, kayak_rt::nil()), none, no)
                }
            }
            made__load__2__expander::MxNodesKids::KDesc(xs) => {
                Product_11_12_13_14(int_lit(5), xs, none, no)
            }
            made__load__2__expander::MxNodesKids::MxNodesKSeq(x) => {
                Product_11_12_13_14(int_lit(6), kayak_rt::cons(x, kayak_rt::nil()), none, no)
            }
            made__load__2__expander::MxNodesKids::KForm(x) => {
                Product_11_12_13_14(int_lit(7), kayak_rt::cons(x, kayak_rt::nil()), none, no)
            }
            _ => {
                let y = tagcase_;
                Product_11_12_13_14(int_lit(8), nil::<Int>(), none, kayak_rt::cons(node_syn(mxp, maker_st, i), kayak_rt::nil()))
            }
        }
    }

    pub fn anodes_from<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut i: Int, mut n: Int, mut fs: MxNodesFound, mut out: Anodes) -> Anodes {
        loop {
            if _eq(i, n) {
                return the::<Anodes>(reverse(out));
            } else {
                (i, out) = (_plus(i, int_lit(1)), cons(anode_of(mxp, maker_st, i, fs), out));
                continue;
            }
        }
    }

    pub fn alpha_nodes<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, s: kayak_rt::Handle<'static, Syn>, made: kayak_rt::Handle<'static, Sty>) -> Result<Anodes, Unwind> {
        let mx_nodes_found = program_scoped(mxp, maker_st, mx_fail, made, s, false, nil::<Symbol>())?.1;
        Ok(anodes_from(mxp, maker_st, int_lit(0), get(maker_st.nnodes.get().unwrap()), mx_nodes_found, nil::<Product_11_12_13_14<Int, List<Int>, List<Symbol>, List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>>>()))
    }

    pub fn ints_same_p(mut xs: List<Int>, mut ys: List<Int>) -> bool {
        loop {
            if null_p(xs) {
                return null_p(ys);
            } else if null_p(ys) {
                return false;
            } else {
                if _eq(car(xs), car(ys)) {
                    (xs, ys) = (cdr(xs), cdr(ys));
                    continue;
                } else {
                    return false;
                }
            }
        }
    }

    pub fn names_same_p(mut xs: List<Symbol>, mut ys: List<Symbol>) -> bool {
        loop {
            if null_p(xs) {
                return null_p(ys);
            } else if null_p(ys) {
                return false;
            } else {
                if symbol_eq_p(car(xs), car(ys)) {
                    (xs, ys) = (cdr(xs), cdr(ys));
                    continue;
                } else {
                    return false;
                }
            }
        }
    }

    pub fn syn_same_p<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut a: kayak_rt::Handle<'static, Syn>, mut b: kayak_rt::Handle<'static, Syn>) -> Result<bool, Unwind> {
        loop {
            let tagcase_ = a;
            match *tagcase_ {
                made__load__2__expander::Syn::MxEagerReaderTypesLst(xs, d, c, e, x) => {
                    let tagcase_ = b;
                    match *tagcase_ {
                        made__load__2__expander::Syn::MxEagerReaderTypesLst(ys, d2, c2, e2, x2) => {
                            return Ok(all_same_p(mxp, maker_st, xs, ys)?);
                        }
                        _ => {
                            let y = tagcase_;
                            return Ok(false);
                        }
                    }
                }
                made__load__2__expander::Syn::Dotted(xs, t, d, c, e, x) => {
                    let tagcase_ = b;
                    match *tagcase_ {
                        made__load__2__expander::Syn::Dotted(ys, u, d2, c2, e2, x2) => {
                            if all_same_p(mxp, maker_st, xs, ys)? {
                                (a, b) = (t, u);
                                continue;
                            } else {
                                return Ok(false);
                            }
                        }
                        _ => {
                            let y = tagcase_;
                            return Ok(false);
                        }
                    }
                }
                made__load__2__expander::Syn::Atom(d, c, e, x) => {
                    if syn_symbol_p(a) {
                        return Ok((syn_symbol_p(b) && symbol_eq_p(syn_symbol(mxp, maker_st, a)?, syn_symbol(mxp, maker_st, b)?)));
                    } else {
                        return Ok(mx_match_same_atom_p(a, b));
                    }
                }
                _ => {
                    let y = tagcase_;
                    return Ok(false);
                }
            }
        }
    }

    pub fn all_same_p<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut xs: SynsA, mut ys: SynsA) -> Result<bool, Unwind> {
        loop {
            if null_p(xs) {
                return Ok(null_p(ys));
            } else {
                if not(null_p(ys)) {
                    if syn_same_p(mxp, maker_st, car(xs), car(ys))? {
                        (xs, ys) = (cdr(xs), cdr(ys));
                        continue;
                    } else {
                        return Ok(false);
                    }
                } else {
                    return Ok(false);
                }
            }
        }
    }

    pub fn anode_same_p<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, a: Anode, b: Anode) -> Result<bool, Unwind> {
        Ok((_eq(a.0, b.0) && ints_same_p(a.1, b.1) && names_same_p(a.2, b.2) && (null_p(a.3) || (not(null_p(b.3)) && syn_same_p(mxp, maker_st, car(a.3), car(b.3))?))))
    }

    pub fn alpha_same_p<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut r#as: Anodes, mut bs: Anodes) -> Result<bool, Unwind> {
        loop {
            if null_p(r#as) {
                return Ok(null_p(bs));
            } else if null_p(bs) {
                return Ok(false);
            } else {
                if anode_same_p(mxp, maker_st, car(r#as), car(bs))? {
                    (r#as, bs) = (cdr(r#as), cdr(bs));
                    continue;
                } else {
                    return Ok(false);
                }
            }
        }
    }

    pub fn mx_contracts_fresh_of<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut n: Symbol, mut fresh: MxContractsRenames, mut made: Int) -> List<Symbol> {
        loop {
            if null_p(fresh) {
                return nil::<Symbol>();
            } else if (symbol_eq_p(n, car(fresh).0) || string_eq_p(symbol_to_string(n), string_append(str_lit("%~"), string_append(mx_fresh_tag_of(mxp, maker_st, made), string_append(str_lit(":"), symbol_to_string(car(fresh).0)))))) {
                return kayak_rt::cons(car(fresh).1, kayak_rt::nil());
            } else {
                fresh = cdr(fresh);
                continue;
            }
        }
    }

    pub fn mx_contracts_escaped<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut ns: Anodes, mut fresh: MxContractsRenames, mut made: Int) -> List<Symbol> {
        loop {
            if null_p(ns) {
                return nil::<Symbol>();
            } else {
                let x = if (_eq(car(ns).0, int_lit(4)) && not(null_p(car(ns).2))) {
                    mx_contracts_fresh_of(mxp, maker_st, car(car(ns).2), fresh, made)
                } else {
                    nil::<Symbol>()
                };
                if null_p(x) {
                    ns = cdr(ns);
                    continue;
                } else {
                    return x;
                }
            }
        }
    }

    pub fn contract_held<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, in_use: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, s: kayak_rt::Handle<'static, Syn>, out: kayak_rt::Handle<'static, Syn>, out2: kayak_rt::Handle<'static, Syn>, fresh: MxContractsRenames, made: Int, ty: kayak_rt::Handle<'static, Sty>) -> Result<(), Unwind> {
        let ours = kayak_rt::closure3((in_use, s,), |(in_use, s,), m: Str, a: Int, b: Int| {
            Ok(match in_use.call(string_append(str_lit("its expansion: "), m), syn_start(s), syn_end(s))? {})
        });
        let a = alpha_nodes(mxp, maker_st, ours, out, ty)?;
        let b = alpha_nodes(mxp, maker_st, ours, out2, ty)?;
        if alpha_same_p(mxp, maker_st, a, b)? {
            Ok(())
        } else {
            let x = mx_contracts_escaped(mxp, maker_st, b, fresh, made);
            Ok(match in_use.call(if null_p(x) {
                str_lit("its expansion depends on how its use's bound names are spelled")
            } else {
                string_append(str_lit("its expansion places `"), string_append(symbol_to_string(car(x)), string_append(str_lit("` where its contract does not put it in `"), string_append(symbol_to_string(car(x)), str_lit("`'s scope")))))
            }, syn_start(s), syn_end(s))? {})
        }
    }

    pub fn mx_contracts_named_in_p(mut x: Product_11_12<Symbol, bool>, mut ys: NamedNs) -> bool {
        loop {
            if not(null_p(ys)) {
                if (symbol_eq_p(x.0, car(ys).0) && mx_eq_p(x.1, car(ys).1)) {
                    return true;
                } else {
                    ys = cdr(ys);
                    continue;
                }
            } else {
                return false;
            }
        }
    }

    pub fn own_name_p(n: Symbol, own: Str) -> bool {
        let (s, k) = (symbol_to_string(n), string_length(own));
        (_gt(k, int_lit(0)) && _gt_eq(string_length(s), k) && string_eq_p(substring(s, int_lit(0), k), own))
    }

    pub fn named_not_in(mut xs: NamedNs, mut ys: NamedNs, mut own: Str) -> List<Symbol> {
        loop {
            if null_p(xs) {
                return nil::<Symbol>();
            } else if (mx_contracts_named_in_p(car(xs), ys) || own_name_p(car(xs).0, own)) {
                xs = cdr(xs);
                continue;
            } else {
                return kayak_rt::heap_cons(car(xs).0, kayak_rt::nil());
            }
        }
    }

    #[inline]
    pub fn said_not_yet<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, at: kayak_rt::Handle<'static, Syn>) -> Result<(), Unwind> {
        Ok(match fail_at(mxp, maker_st, mx_fail, str_lit("a contract whose uses define what a part of theirs defines: not yet"), at)? {})
    }

    pub fn said_names<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut r#as: Atms, mut parts: SynsA, mut at: kayak_rt::Handle<'static, Syn>) -> Result<NamedNs, Unwind> {
        loop {
            if null_p(r#as) {
                return Ok(nil::<Product_11_12<Symbol, bool>>());
            } else {
                let tagcase_ = car(r#as);
                match *tagcase_ {
                    made__load__2__expander::Atm::AtmVar(b, d, g) => {
                        let p = nth(parts, part_number(b));
                        if syn_symbol_p(p) {
                            return Ok(cons(Product_11_12(syn_symbol(mxp, maker_st, p)?, d), said_names(mxp, maker_st, mx_fail, cdr(r#as), parts, at)?));
                        } else {
                            match fail_at(mxp, maker_st, mx_fail, str_lit("a binder that is not a name"), p)? {};
                            return Ok(nil::<Product_11_12<Symbol, bool>>());
                        }
                    }
                    made__load__2__expander::Atm::AtmRibOf(n) => {
                        said_not_yet(mxp, maker_st, mx_fail, at)?;
                        return Ok(nil::<Product_11_12<Symbol, bool>>());
                    }
                    made__load__2__expander::Atm::AtmLit(i, d) => {
                        r#as = cdr(r#as);
                        continue;
                    }
                }
            }
        }
    }

    pub fn contract_said<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, sig: kayak_rt::Handle<'static, Sty>, operands: kayak_rt::Handle<'static, Syn>) -> Result<NamedNs, Unwind> {
        let r#use = {
            nodes_reset_x(mxp, maker_st);
            align(mxp, maker_st, mx_fail, int_lit(2), the::<Pvars>(nil::<Product_11_12<Symbol, Product_11_12_13_14_15<kayak_rt::Handle<'static, made__load__2__expander::Sty>, List<kayak_rt::Handle<'static, made__load__2__expander::Level>>, bool, List<Product_11_12<List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>, List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>>>, Int>>>()), sig, operands, int_lit(-1), nil::<bool>())?
        };
        let leaves = leaves_of(mxp, maker_st, mx_fail, int_lit(0), get(maker_st.nnodes.get().unwrap()), nil::<Product_11_12<Int, Int>>())?;
        let made = {
            set(maker_st.pseudo_parts.get().unwrap(), nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>());
            pseudo_pattern(mxp, maker_st, operands, leaves)
        };
        let parts = the::<SynsA>(reverse(get(maker_st.pseudo_parts.get().unwrap())));
        let root = {
            nodes_reset_x(mxp, maker_st);
            align(mxp, maker_st, mx_fail, int_lit(0), the::<Pvars>(nil::<Product_11_12<Symbol, Product_11_12_13_14_15<kayak_rt::Handle<'static, made__load__2__expander::Sty>, List<kayak_rt::Handle<'static, made__load__2__expander::Level>>, bool, List<Product_11_12<List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>, List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>>>, Int>>>()), sig, made, int_lit(-1), nil::<bool>())?
        };
        let mx_nodes_found = mx_scopes_walk(mxp, maker_st, mx_fail, root, maker_st.env_empty.get().unwrap(), false, int_lit(0))?;
        let e = node_export(mxp, maker_st, root);
        if null_p(e) {
            Ok(nil::<Product_11_12<Symbol, bool>>())
        } else {
            let x = mx_exports_exports_of(evaluate(mxp, maker_st, mx_fail, car(e).0, car(e).1, made)?);
            if null_p(x.1) {
                Ok(said_names(mxp, maker_st, mx_fail, x.0, parts, operands)?)
            } else {
                said_not_yet(mxp, maker_st, mx_fail, operands)?;
                Ok(nil::<Product_11_12<Symbol, bool>>())
            }
        }
    }

    pub fn atm_defines<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut r#as: Atms, mut out: NamedNs) -> NamedNs {
        loop {
            if null_p(r#as) {
                return out;
            } else {
                (r#as, out) = (cdr(r#as), {
                    let tagcase_ = car(r#as);
                    match *tagcase_ {
                        made__load__2__expander::Atm::AtmLit(b, d) => {
                            let tagcase_ = node_kids(mxp, maker_st, b);
                            match *tagcase_ {
                                made__load__2__expander::MxNodesKids::KBinder(m, e) => {
                                    if mx_contracts_named_in_p(Product_11_12(m, d), out) {
                                        out
                                    } else {
                                        cons(Product_11_12(m, d), out)
                                    }
                                }
                                _ => {
                                    let y = tagcase_;
                                    out
                                }
                            }
                        }
                        _ => {
                            let y = tagcase_;
                            out
                        }
                    }
                });
                continue;
            }
        }
    }

    pub fn level_defines<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut ls: Levels, mut out: NamedNs) -> NamedNs {
        loop {
            if null_p(ls) {
                return out;
            } else {
                (ls, out) = (cdr(ls), {
                    let tagcase_ = car(ls);
                    match *tagcase_ {
                        made__load__2__expander::Level::LvRib(r#as) => {
                            atm_defines(mxp, maker_st, r#as, out)
                        }
                        _ => {
                            let y = tagcase_;
                            out
                        }
                    }
                });
                continue;
            }
        }
    }

    pub fn defines_from<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut i: Int, mut n: Int, mut out: NamedNs) -> Result<NamedNs, Unwind> {
        loop {
            if _eq(i, n) {
                return Ok(out);
            } else {
                (i, out) = (_plus(i, int_lit(1)), {
                    let k = mx_types_kind_of(node_core(mxp, maker_st, i));
                    if (_eq(k, int_lit(14)) || _eq(k, int_lit(11))) {
                        let tagcase_ = node_kids(mxp, maker_st, i);
                        match *tagcase_ {
                            made__load__2__expander::MxNodesKids::KForm(x) => {
                                let ex = node_export(mxp, maker_st, x);
                                if null_p(ex) {
                                    out
                                } else {
                                    level_defines(mxp, maker_st, evaluate(mxp, maker_st, mx_fail, car(ex).0, car(ex).1, node_syn(mxp, maker_st, i))?, out)
                                }
                            }
                            _ => {
                                let y = tagcase_;
                                out
                            }
                        }
                    } else {
                        out
                    }
                });
                continue;
            }
        }
    }

    pub fn expansion_defines<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, out: kayak_rt::Handle<'static, Syn>) -> Result<NamedNs, Unwind> {
        let scoped = program_scoped(mxp, maker_st, mx_fail, s_defn(), out, false, nil::<Symbol>())?;
        let ds = {
            set(maker_st.program_walk.get().unwrap(), true);
            defines_from(mxp, maker_st, mx_fail, int_lit(0), get(maker_st.nnodes.get().unwrap()), nil::<Product_11_12<Symbol, bool>>())?
        };
        set(maker_st.program_walk.get().unwrap(), false);
        Ok(ds)
    }

    pub fn defined_held<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, sig: kayak_rt::Handle<'static, Sty>, operands: kayak_rt::Handle<'static, Syn>, out: kayak_rt::Handle<'static, Syn>, made: Int) -> Result<(), Unwind> {
        let said = contract_said(mxp, maker_st, mx_fail, sig, operands)?;
        let ours = kayak_rt::closure3((mx_fail,), |(mx_fail,), m: Str, a: Int, b: Int| {
            Ok(match mx_fail.call(string_append(str_lit("its expansion: "), m), a, b)? {})
        });
        let defines = expansion_defines(mxp, maker_st, ours, out)?;
        let own = string_append(str_lit("%~"), string_append(mx_fresh_tag_of(mxp, maker_st, made), str_lit(":")));
        let extra = named_not_in(defines, said, own);
        let missing = named_not_in(said, defines, str_lit(""));
        if not(null_p(extra)) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit("its expansion defines `"), string_append(symbol_to_string(car(extra)), string_append(str_lit("`, which its contract does not say a use defines, "), str_lit("nor is it its own (an alias, as `rename` makes one)")))), out)? {})
        } else if not(null_p(missing)) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit("its contract says a use defines `"), string_append(symbol_to_string(car(missing)), str_lit("`, and its expansion does not"))), out)? {})
        } else {
            Ok(())
        }
    }

