    pub fn syn_at_addr(mut s: kayak_rt::Handle<'static, Syn>, mut a: Addr) -> SynsA {
        loop {
            if null_p(a) {
                return kayak_rt::heap_cons(s, kayak_rt::nil());
            } else if null_p(split(s)) {
                return nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>();
            } else {
                (s, a) = (if car(a) {
                    car(split(s))
                } else {
                    nth(split(s), int_lit(1))
                }, cdr(a));
                continue;
            }
        }
    }

    pub fn name_in_from_p(mut n: Symbol, mut ns: MxParserTypesNames, mut k: Int) -> bool {
        loop {
            if null_p(ns) {
                return false;
            } else if _gt(k, int_lit(0)) {
                (ns, k) = (cdr(ns), _minus(k, int_lit(1)));
                continue;
            } else {
                if symbol_eq_p(n, car(ns)) {
                    return true;
                } else {
                    (ns, k) = (cdr(ns), int_lit(0));
                    continue;
                }
            }
        }
    }

    pub fn same_signature_p<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, n: Symbol, said: kayak_rt::Handle<'static, Syn>) -> Result<bool, Unwind> {
        let (have, want) = (car(macro_of(n, get(maker_st.defined.get().unwrap()))), signature_of(mxp, maker_st, mx_fail, said)?);
        Ok((null_p(want.0) && null_p(have.2) && _eq(have.3, want.2) && sub_p(mxp, maker_st, have.0, want.1, nil::<Product_11_12<kayak_rt::Handle<'static, made__load__2__expander::Sty>, kayak_rt::Handle<'static, made__load__2__expander::Sty>>>()) && sub_p(mxp, maker_st, want.1, have.0, nil::<Product_11_12<kayak_rt::Handle<'static, made__load__2__expander::Sty>, kayak_rt::Handle<'static, made__load__2__expander::Sty>>>())))
    }

    pub fn syntax_held_each<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut name: Symbol, mut s: kayak_rt::Handle<'static, Syn>, mut from: Int, mut es: Entries) -> Result<(), Unwind> {
        loop {
            if null_p(es) {
                return Ok(());
            } else {
                let d = car(es).1;
                if _lt(d, int_lit(100)) {
                    es = cdr(es);
                    continue;
                } else {
                    let said = syntax_sig_of(mxp, maker_st, d);
                    let shown = show_syn(said);
                    let part = syn_at_addr(nth(split(s), int_lit(1)), car(es).0);
                    let x = if (not(null_p(part)) && syn_symbol_p(car(part))) {
                        syn_name(car(part))
                    } else {
                        str_lit("")
                    };
                    let refused = kayak_rt::closure1((mx_fail, name, s,), |(mx_fail, name, s,), m: Str| {
                        Ok(match mx_fail.call(string_append(str_lit("a use of `"), string_append(symbol_to_string(name), string_append(str_lit("`: "), m))), syn_start(s), syn_end(s))? {})
                    });
                    if string_eq_p(x, str_lit("")) {
                        return Ok(match refused.call(string_append(str_lit("its signature says a macro of `"), string_append(shown, string_append(str_lit("` is "), str_lit("defined at a part that is not a name")))))? {});
                    } else if not(name_in_from_p(string_to_symbol(x), get(maker_st.made_syntax.get().unwrap()), from)) {
                        return Ok(match refused.call(string_append(str_lit("its signature says it defines `"), string_append(x, string_append(str_lit("`, a macro "), string_append(str_lit("of `"), string_append(shown, str_lit("`, and its expansion does not")))))))? {});
                    } else if not(same_signature_p(mxp, maker_st, mx_fail, string_to_symbol(x), said)?) {
                        return Ok(match refused.call(string_append(str_lit("its signature says `"), string_append(x, string_append(str_lit("` is a macro of `"), string_append(shown, string_append(str_lit("`, and its expansion defines one of "), str_lit("another signature")))))))? {});
                    } else {
                        es = cdr(es);
                        continue;
                    }
                }
            }
        }
    }

    pub fn syntax_held<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, name: Symbol, s: kayak_rt::Handle<'static, Syn>, from: Int) -> Result<(), Unwind> {
        let m = macro_of(name, get(maker_st.defined.get().unwrap()));
        if null_p(m) {
            Ok(())
        } else {
            let tagcase_ = car(m).0;
            match *tagcase_ {
                made__load__2__expander::Sty::SExport(body, b) => {
                    let tagcase_ = b;
                    match *tagcase_ {
                        made__load__2__expander::MxTypesBind::BindRib(es) => {
                            Ok(syntax_held_each(mxp, maker_st, mx_fail, name, s, from, es)?)
                        }
                        _ => {
                            let y = tagcase_;
                            Ok(())
                        }
                    }
                }
                _ => {
                    let y = tagcase_;
                    Ok(())
                }
            }
        }
    }

    #[inline]
