    pub fn mx_procedural_run<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, code: Str) -> kayak_rt::Sum {
        let a = mx_expand_procedural(mxp, maker_st, code);
        if (_gt(string_length(a), int_lit(0)) && char_eq_p(string_ref(a, int_lit(0)), '=')) {
            kayak_rt::sum_new::<Str>(const { kayak_rt::tag_hash("ok") }, "ok", substring(a, int_lit(1), string_length(a)))
        } else {
            kayak_rt::sum_new::<Str>(const { kayak_rt::tag_hash("failed") }, "failed", if _gt(string_length(a), int_lit(0)) {
                substring(a, int_lit(1), string_length(a))
            } else {
                a
            })
        }
    }

    pub fn mx_procedural_escaped(mut s: Str, mut i: Int, mut out: Str) -> Str {
        loop {
            if _gt_eq(i, string_length(s)) {
                return out;
            } else {
                let c = string_ref(s, i);
                (i, out) = (_plus(i, int_lit(1)), string_append(out, if char_eq_p(c, '"') {
                    str_lit("\\\"")
                } else if char_eq_p(c, '\\') {
                    str_lit("\\\\")
                } else if char_eq_p(c, integer_to_char(int_lit(10))) {
                    str_lit("\\n")
                } else {
                    char_to_string(c)
                }));
                continue;
            }
        }
    }

    pub fn char_text(c: char) -> Str {
        if char_eq_p(c, ' ') {
            str_lit("#\\space")
        } else if char_eq_p(c, integer_to_char(int_lit(10))) {
            str_lit("#\\newline")
        } else if char_eq_p(c, integer_to_char(int_lit(9))) {
            str_lit("#\\tab")
        } else {
            string_append(str_lit("#\\"), char_to_string(c))
        }
    }

    pub fn datum_text(d: kayak_rt::value::Value) -> Str {
        if kayak_rt::value::null_p(d) {
            str_lit("()")
        } else if symbol_p(d) {
            symbol_to_string(kayak_rt::value::unbox::<Symbol>(d))
        } else if mx_keyword_p(d) {
            string_append(str_lit("#:"), symbol_to_string(mx_keyword_to_symbol(d)))
        } else if string_p(d) {
            string_append(str_lit("\""), string_append(mx_procedural_escaped(kayak_rt::value::unbox::<Str>(d), int_lit(0), str_lit("")), str_lit("\"")))
        } else if char_p(d) {
            char_text(kayak_rt::value::unbox::<char>(d))
        } else if int_p(d) {
            int_to_string(kayak_rt::value::unbox::<Int>(d))
        } else if f64_p(d) {
            f64_to_string(kayak_rt::value::unbox::<f64>(d))
        } else if bool_p(d) {
            if kayak_rt::value::unbox::<bool>(d) {
                str_lit("#t")
            } else {
                str_lit("#f")
            }
        } else {
            str_lit("#u")
        }
    }

    pub fn syn_text(s: kayak_rt::Handle<'static, Syn>) -> Str {
        let tagcase_ = s;
        match *tagcase_ {
            made__load__2__expander::Syn::Atom(d, a, b, x) => {
                datum_text(d)
            }
            made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                string_append(str_lit("("), string_append(syns_text(items), str_lit(")")))
            }
            made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                string_append(str_lit("("), string_append(syns_text(items), string_append(str_lit(" . "), string_append(syn_text(tail), str_lit(")")))))
            }
            made__load__2__expander::Syn::Vec(items, d, a, b, x) => {
                string_append(str_lit("#("), string_append(syns_text(items), str_lit(")")))
            }
        }
    }

    pub fn syns_text(xs: SynsA) -> Str {
        if null_p(xs) {
            str_lit("")
        } else if null_p(cdr(xs)) {
            syn_text(car(xs))
        } else {
            string_append(syn_text(car(xs)), string_append(str_lit(" "), syns_text(cdr(xs))))
        }
    }

    pub fn copy_sources<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut from: Array<Product_11_12<Int, Int>>, mut to: Array<Product_11_12<Int, Int>>, mut i: Int) -> () {
        loop {
            if _eq(i, array_length(from)) {
                return ();
            } else {
                array_set_x(to, i, array_ref(from, i));
                i = _plus(i, int_lit(1));
                continue;
            }
        }
    }

    pub fn new_source_key<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, p: Int, made: Int) -> Int {
        let i = get(maker_st.nsources.get().unwrap());
        if _eq(i, array_length(get(maker_st.sources.get().unwrap()))) {
            let bigger = the::<Array<Product_11_12<Int, Int>>>(make_array(_star(int_lit(2), i), Product_11_12(int_lit(0), int_lit(0))));
            copy_sources(mxp, maker_st, get(maker_st.sources.get().unwrap()), bigger, int_lit(0));
            set(maker_st.sources.get().unwrap(), bigger)
        } else {
            ()
        };
        array_set_x(get(maker_st.sources.get().unwrap()), i, Product_11_12(p, made));
        set(maker_st.nsources.get().unwrap(), _plus(i, int_lit(1)));
        _plus(maker_st.source_base.get().unwrap(), i)
    }

