    pub fn checked_from<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut i: Int, mut n: Int, mut name: Symbol, mut sig: kayak_rt::Handle<'static, Sty>, mut ps: Pvars, mut out: List<Int>) -> Result<List<Int>, Unwind> {
        loop {
            if _eq(i, n) {
                return Ok(out);
            } else {
                let s = node_syn(mxp, maker_st, i);
                let parts = split(s);
                let h = if (null_p(parts) || not(syn_symbol_p(car(parts))) || pvar_p(syn_symbol(mxp, maker_st, car(parts))?, ps) || {
                    let tagcase_ = node_kids(mxp, maker_st, i);
                    match *tagcase_ {
                        made__load__2__expander::MxNodesKids::KForm(x) => {
                            false
                        }
                        _ => {
                            let y = tagcase_;
                            true
                        }
                    }
                }) {
                    nil::<Symbol>()
                } else {
                    kayak_rt::cons(syn_symbol(mxp, maker_st, car(parts))?, kayak_rt::nil())
                };
                let checked = (not(null_p(h)) && if macro_p(mxp, maker_st, car(h)) {
                    (_eq(makes(mxp, maker_st, car(h)), int_lit(0)) || _eq(makes(mxp, maker_st, car(h)), int_lit(1)))
                } else {
                    (symbol_eq_p(car(h), name) && fits_apart_p(mxp, maker_st, sig, nth(parts, int_lit(1)), ps)?)
                });
                (i, out) = (_plus(i, int_lit(1)), if checked {
                    cons(syn_start(s), out)
                } else {
                    out
                });
                continue;
            }
        }
    }

