    pub fn respanned(s: kayak_rt::Handle<'static, Syn>, a: Int, b: Int, x: Int) -> kayak_rt::Handle<'static, Syn> {
        let tagcase_ = s;
        match *tagcase_ {
            made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, c, e, y) => {
                mx_eager_reader_types_lst(respanned_each(items, a, b, x), d, a, b, x)
            }
            made__load__2__expander::Syn::Dotted(items, tail, d, c, e, y) => {
                dotted(respanned_each(items, a, b, x), respanned(tail, a, b, x), d, a, b, x)
            }
            made__load__2__expander::Syn::Vec(items, d, c, e, y) => {
                vec(respanned_each(items, a, b, x), d, a, b, x)
            }
            made__load__2__expander::Syn::Atom(d, c, e, y) => {
                atom(d, a, b, x)
            }
        }
    }

