    pub fn expand<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, form: kayak_rt::Handle<'static, Syn>) -> Result<kayak_rt::Handle<'static, Syn>, Unwind> {
        if (null_p(get(maker_st.defined.get().unwrap())) && not(names_macro_p(mxp, maker_st, form)?)) {
            Ok(form)
        } else {
            let n = chain_begun_x(mxp, maker_st, mx_fail, form)?;
            if _lt(n, int_lit(0)) {
                Ok(form)
            } else {
                set(maker_st.budget.get().unwrap(), n);
                Ok(at_place(expand_in(mxp, maker_st, mx_fail, form, nil::<Product_11_12<Int, Int>>())?, syn_start(form), syn_end(form), int_lit(0)))
            }
        }
    }

    pub fn expand_defn<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, s: kayak_rt::Handle<'static, Syn>) -> Result<SynsA, Unwind> {
        let items = list_items(s);
        let hd = if null_p(items) {
            s
        } else {
            car(items)
        };
        let head = if syn_symbol_p(hd) {
            syn_name(hd)
        } else {
            str_lit("")
        };
        if (syn_symbol_p(hd) && macro_p(mxp, maker_st, syn_symbol(mxp, maker_st, hd)?)) {
            if use_entered_p(mxp, maker_st, mx_fail, syn_symbol(mxp, maker_st, hd)?, s, get(maker_st.budget.get().unwrap()))? {
                set(maker_st.budget.get().unwrap(), _minus(get(maker_st.budget.get().unwrap()), int_lit(1)));
                let from = made_syntax_count(mxp, maker_st);
                let made = expand_defn(mxp, maker_st, mx_fail, expand_use(mxp, maker_st, mx_fail, syn_symbol(mxp, maker_st, hd)?, s)?)?;
                syntax_held(mxp, maker_st, mx_fail, syn_symbol(mxp, maker_st, hd)?, s, from)?;
                use_left_x(mxp, maker_st);
                Ok(made)
            } else {
                Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
            }
        } else if string_eq_p(head, str_lit("begin")) {
            Ok(expand_defns(mxp, maker_st, mx_fail, cdr(items))?)
        } else if (string_eq_p(head, str_lit("define-syntax")) || string_eq_p(head, str_lit("define-syntax-rec"))) {
            made_syntax_add_x(mxp, maker_st, define_macro(mxp, maker_st, mx_fail, s, nil::<Product_11_12_13_14_15<Symbol, List<Symbol>, List<Symbol>, List<Product_11_12<Symbol, Symbol>>, List<Symbol>>>())?);
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            Ok(kayak_rt::cons(expand_in(mxp, maker_st, mx_fail, s, nil::<Product_11_12<Int, Int>>())?, kayak_rt::nil()))
        }
    }

    #[inline]
    pub fn expand_defns<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, xs: SynsA) -> Result<SynsA, Unwind> {
        if null_p(xs) {
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            Ok(append(expand_defn(mxp, maker_st, mx_fail, car(xs))?, expand_defns(mxp, maker_st, mx_fail, cdr(xs))?))
        }
    }

    pub fn expand_top<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, form: kayak_rt::Handle<'static, Syn>) -> Result<SynsA, Unwind> {
        let items = list_items(form);
        if (not(null_p(items)) && syn_symbol_p(car(items)) && makes_top_defns_p(mxp, maker_st, syn_symbol(mxp, maker_st, car(items))?)) {
            let n = {
                made_syntax_reset_x(mxp, maker_st);
                chain_begun_x(mxp, maker_st, mx_fail, form)?
            };
            if _lt(n, int_lit(0)) {
                Ok(kayak_rt::cons(form, kayak_rt::nil()))
            } else {
                set(maker_st.budget.get().unwrap(), n);
                Ok(at_places(expand_defn(mxp, maker_st, mx_fail, form)?, syn_start(form), syn_end(form)))
            }
        } else {
            Ok(kayak_rt::cons(expand(mxp, maker_st, mx_fail, form)?, kayak_rt::nil()))
        }
    }

