    pub fn symbol_in<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut s: kayak_rt::Handle<'static, Syn>, mut n: Symbol) -> Result<SynsA, Unwind> {
        loop {
            if syn_symbol_p(s) {
                if symbol_eq_p(syn_symbol(mxp, maker_st, s)?, n) {
                    return Ok(kayak_rt::cons(s, kayak_rt::nil()));
                } else {
                    return Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>());
                }
            } else if null_p(split(s)) {
                return Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>());
            } else {
                let first = symbol_in(mxp, maker_st, car(split(s)), n)?;
                if null_p(first) {
                    s = nth(split(s), int_lit(1));
                    continue;
                } else {
                    return Ok(first);
                }
            }
        }
    }

    pub fn pattern_place<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, c: Clause, n: Symbol) -> Result<kayak_rt::Handle<'static, Syn>, Unwind> {
        let found = symbol_in(mxp, maker_st, c.0, n)?;
        if null_p(found) {
            Ok(c.0)
        } else {
            Ok(car(found))
        }
    }

    pub fn bvar_binds<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut c: Clause, mut ps: Pvars, mut out: MxMatchBinds) -> Result<MxMatchBinds, Unwind> {
        loop {
            if null_p(ps) {
                return Ok(out);
            } else {
                let n = car(ps).0;
                let k = mx_types_kind_of(car(ps).1.0);
                if (_eq(k, int_lit(0)) || _eq(k, int_lit(10))) {
                    ps = cdr(ps);
                    continue;
                } else if _eq(k, int_lit(1)) {
                    let f = fresh_symbol(mxp, maker_st, string_append(str_lit("%"), string_append(symbol_to_string(n), str_lit(":"))));
                    (ps, out) = (cdr(ps), append(out, the::<MxMatchBinds>(kayak_rt::cons(Product_11_12(n, mk_symbol(symbol_to_string(f), int_lit(0), int_lit(0))), kayak_rt::nil()))));
                    continue;
                } else {
                    match fail_at(mxp, maker_st, mx_fail, string_append(str_lit("`"), string_append(symbol_to_string(n), string_append(str_lit("` is not an `expr`, a "), string_append(str_lit("`lambda` or a `bvar`: a macro whose parts are "), str_lit("typed is checked once, of those alone, not yet"))))), pattern_place(mxp, maker_st, c, n)?)? {};
                    return Ok(out);
                }
            }
        }
    }

