    pub fn map_shapes<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: List<Int>) -> Result<List<MxParserTypesShapes>, Unwind> {
        if null_p(ps) {
            Ok(nil::<List<kayak_rt::Handle<'static, made__load__2__expander::MxParserTypesShape>>>())
        } else {
            Ok(cons({
                let p = car(ps);
                if _lt(p, int_lit(0)) {
                    nil::<kayak_rt::Handle<'static, made__load__2__expander::MxParserTypesShape>>()
                } else {
                    let tagcase_ = node_kids(mxp, maker_st, p);
                    match *tagcase_ {
                        made__load__2__expander::MxNodesKids::KBinder(n, d) => {
                            binder_shape(mxp, maker_st, mx_fail, p)?
                        }
                        _ => {
                            let y = tagcase_;
                            mx_shaper_ty_shape(mxp, maker_st, mx_fail, elem(mxp, maker_st, p, int_lit(1)))?
                        }
                    }
                }
            }, map_shapes(mxp, maker_st, mx_fail, cdr(ps))?))
        }
    }

