    pub fn writings<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut k: Int, mut n: Int, mut out: List<Writing>) -> Result<List<Writing>, Unwind> {
        loop {
            if _eq(k, n) {
                return Ok(out);
            } else {
                (k, out) = (_plus(k, int_lit(1)), {
                    let s = node_syn(mxp, maker_st, k);
                    if (mx_shaper_form_node_p(mxp, maker_st, k) && opens_p(mxp, maker_st, s)? && null_p(writing_at(node_path(mxp, maker_st, k), out)) && not(toplevel_or_fx_p(s)) && _gt_eq(elem(mxp, maker_st, k, int_lit(1)), int_lit(0))) {
                        let a = asked_of(mxp, maker_st, elem(mxp, maker_st, k, int_lit(1)));
                        cons(Product_11_12(node_path(mxp, maker_st, k), if a.1 {
                            nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
                        } else {
                            kayak_rt::cons(asked_written(a, s), kayak_rt::nil())
                        }), out)
                    } else {
                        out
                    }
                });
                continue;
            }
        }
    }

