    pub fn written_under<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: kayak_rt::Handle<'static, Syn>, ws: List<Writing>) -> Result<kayak_rt::Handle<'static, Syn>, Unwind> {
        if null_p(ws) {
            Ok(s)
        } else {
            let tagcase_ = s;
            match *tagcase_ {
                made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                    let items2 = written_items(mxp, maker_st, items, ws, written_here(mxp, maker_st, s, ws)?, int_lit(0), a, b)?;
                    Ok(mx_eager_reader_types_lst(items2, kayak_rt::value::list(syn_datums(items2)), a, b, x))
                }
                made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                    let items2 = written_items(mxp, maker_st, items, ws, written_here(mxp, maker_st, s, ws)?, int_lit(0), a, b)?;
                    Ok(dotted(items2, written_under(mxp, maker_st, tail, steps_taken(ws, len(items)))?, kayak_rt::value::list(syn_datums(items2)), a, b, x))
                }
                _ => {
                    let y = tagcase_;
                    Ok(s)
                }
            }
        }
    }

    pub fn written_items<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, items: SynsA, ws: List<Writing>, here: List<List<kayak_rt::Handle<'static, Syn>>>, k: Int, a: Int, b: Int) -> Result<SynsA, Unwind> {
        let record = if null_p(here) {
            the::<SynsA>(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            kayak_rt::cons(atom(kayak_rt::value::ToValue::to_value(mx_symbol_to_keyword(symbol_lit(str_lit("relied")))), a, b, int_lit(0)), kayak_rt::cons(if null_p(car(here)) {
                mk_symbol(str_lit("#f"), a, b)
            } else {
                car(car(here))
            }, kayak_rt::nil()))
        };
        if null_p(items) {
            if _eq(k, int_lit(2)) {
                Ok(record)
            } else {
                Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
            }
        } else if (_eq(k, int_lit(2)) && not(null_p(here))) {
            Ok(append(record, written_items(mxp, maker_st, items, ws, nil::<List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>>(), k, a, b)?))
        } else {
            Ok(cons(written_under(mxp, maker_st, car(items), step_taken(ws, true))?, written_items(mxp, maker_st, cdr(items), step_taken(ws, false), here, _plus(k, int_lit(1)), a, b)?))
        }
    }

