    pub fn fasl_kept_x<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, key: Str, forms: SynsA, input_p: bool) -> Result<(), Unwind> {
        if (null_p(forms) || not(null_p(cdr(forms)))) {
            Ok(())
        } else {
            let form = unshaped(car(forms));
            let r = {
                let prompt_tag__ = maker_st.parse_tag.get().unwrap();
                match (move || -> Result<_, Unwind> {
                    set(maker_st.file_out.get().unwrap(), shaped(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_walk(mxp, maker_st, a0, a1, a2)), form, false)?);
                    Ok(p_ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::MxParserTypesTop>>()))
                })() {
                    Ok(v_) => v_,
                    Err(u_) if u_.is(prompt_tag__) => (kayak_rt::closure1((), |(), r: kayak_rt::Handle<'static, Presult>| {
                        r
                    })).call(prompt_tag__.payload(u_)),
                    Err(u_) => return Err(u_),
                }
            };
            let ok = {
                set(maker_st.program_walk.get().unwrap(), false);
                let tagcase_ = r;
                match *tagcase_ {
                    made__load__2__expander::Presult::PErr(why, a, b) => {
                        false
                    }
                    _ => {
                        let y = tagcase_;
                        true
                    }
                }
            };
            let whole = if ok {
                get(maker_st.file_out.get().unwrap()).1
            } else {
                nil::<kayak_rt::Handle<'static, made__load__2__expander::MxParserTypesShape>>()
            };
            let m = if input_p {
                mx_shaper_member_shape(whole, symbol_lit(str_lit("input")), false)
            } else {
                whole
            };
            let fun = (not(null_p(m)) && {
                let tagcase_ = car(m);
                match *tagcase_ {
                    made__load__2__expander::MxParserTypesShape::ShFun(ps, r) => {
                        true
                    }
                    _ => {
                        let y = tagcase_;
                        false
                    }
                }
            });
            Ok(set(maker_st.file_shapes.get().unwrap(), file_shape_replaced(key, Product_11_12_13_14(key, m, if fun {
                result_of(m)
            } else {
                m
            }, forms), get(maker_st.file_shapes.get().unwrap()))))
        }
    }

