    pub fn parts_items(xs: SynsA, ws: MxShapesParts) -> SynsA {
        if null_p(xs) {
            nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
        } else {
            kayak_rt::heap_cons(parts_under(car(xs), part_step(ws, true)), parts_items(cdr(xs), part_step(ws, false)))
        }
    }

    #[inline]
    pub fn with_parts(s: kayak_rt::Handle<'static, Syn>, path: Addr, ws: List<Product_11_12<Addr, kayak_rt::Handle<'static, Syn>>>) -> kayak_rt::Handle<'static, Syn> {
        parts_under(s, parts_from_top(ws))
    }

    pub fn aliases_resolved<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, x: kayak_rt::Handle<'static, Syn>, hs: MxNodesDefEnvs, tag: kayak_rt::Proc0<'mxp, Result<Str, Unwind>>) -> Result<kayak_rt::Handle<'static, Syn>, Unwind> {
        if not(alias_in_p(mxp, maker_st, x)?) {
            Ok(x)
        } else {
            let w = mx_walk_walked(mxp, maker_st, mx_fail, x, true)?;
            let root = w.0;
            let mx_nodes_found = w.1;
            let made = aliases_written(mxp, maker_st, mx_fail, mx_nodes_found, hs, root_binders(mxp, maker_st, mx_fail, root, x)?, x, Product_11_12(the::<MxShapesParts>(nil::<Product_11_12<List<bool>, kayak_rt::Handle<'static, made__load__2__expander::Syn>>>()), the::<MxShapesInts>(nil::<Int>())))?;
            let fresh = captors_named(mxp, maker_st, made.1, nil::<Product_11_12<Int, Symbol>>(), tag)?;
            let written = append(captors_renamed(mxp, maker_st, mx_nodes_found, fresh, binders_renamed(mxp, maker_st, fresh, nil::<Product_11_12<List<bool>, kayak_rt::Handle<'static, made__load__2__expander::Syn>>>())), made.0);
            aliases_defined_in(mxp, maker_st, mx_fail, root, x)?;
            Ok(with_parts(x, nil::<bool>(), written))
        }
    }

    #[inline]
    pub fn drive_length(fs: List<Str>) -> Int {
        if null_p(fs) {
            int_lit(0)
        } else {
            _plus(int_lit(1), drive_length(cdr(fs)))
        }
    }

    pub fn drive_nth(mut fs: List<Str>, mut i: Int) -> Str {
        loop {
            if _eq(i, int_lit(0)) {
                return car(fs);
            } else {
                (fs, i) = (cdr(fs), _minus(i, int_lit(1)));
                continue;
            }
        }
    }

    pub fn drive_index_in(mut f: Str, mut fs: List<Str>, mut i: Int) -> Int {
        loop {
            if null_p(fs) {
                return int_lit(-1);
            } else if string_eq_p(f, car(fs)) {
                return i;
            } else {
                (fs, i) = (cdr(fs), _plus(i, int_lit(1)));
                continue;
            }
        }
    }

    pub fn drive_file_index<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, f: Str) -> Int {
        let i = drive_index_in(f, get(maker_st.drive_files.get().unwrap()), int_lit(0));
        if _gt_eq(i, int_lit(0)) {
            i
        } else {
            set(maker_st.drive_files.get().unwrap(), append(get(maker_st.drive_files.get().unwrap()), kayak_rt::cons(f, kayak_rt::nil())));
            _minus(drive_length(get(maker_st.drive_files.get().unwrap())), int_lit(1))
        }
    }

    #[inline]
    pub fn drive_place<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, f: Str, pos: i64) -> Int {
        _plus(_star(drive_file_index(mxp, maker_st, f), maker_st.load_base.get().unwrap()), i64_to_int(pos))
    }

    pub fn drive_merge(xs: List<Product_11_12<Int, Int>>, ys: List<Product_11_12<Int, Int>>) -> List<Product_11_12<Int, Int>> {
        if null_p(xs) {
            ys
        } else if null_p(ys) {
            xs
        } else if _lt_eq(car(xs).0, car(ys).0) {
            kayak_rt::heap_cons(car(xs), drive_merge(cdr(xs), ys))
        } else {
            kayak_rt::heap_cons(car(ys), drive_merge(xs, cdr(ys)))
        }
    }

    pub fn drive_split(mut xs: List<Product_11_12<Int, Int>>, mut a: List<Product_11_12<Int, Int>>, mut b: List<Product_11_12<Int, Int>>) -> Product_11_12<List<Product_11_12<Int, Int>>, List<Product_11_12<Int, Int>>> {
        loop {
            if null_p(xs) {
                return Product_11_12(a, b);
            } else {
                (xs, a, b) = (cdr(xs), b, kayak_rt::heap_cons(car(xs), a));
                continue;
            }
        }
    }

    pub fn drive_sorted(xs: List<Product_11_12<Int, Int>>) -> List<Product_11_12<Int, Int>> {
        if (null_p(xs) || null_p(cdr(xs))) {
            xs
        } else {
            let halves = drive_split(xs, nil::<Product_11_12<Int, Int>>(), nil::<Product_11_12<Int, Int>>());
            drive_merge(drive_sorted(halves.0), drive_sorted(halves.1))
        }
    }

    pub fn drive_count_of(mut xs: List<Product_11_12<Int, Int>>, mut n: i64) -> i64 {
        loop {
            if null_p(xs) {
                return n;
            } else {
                (xs, n) = (cdr(xs), i64_plus(n, 1i64));
                continue;
            }
        }
    }

    pub fn drive_fill_x<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut xs: List<Product_11_12<Int, Int>>, mut i: i64) -> () {
        loop {
            if null_p(xs) {
                return ();
            } else {
                array_set_x(get(maker_st.drive_at.get().unwrap()), i64_to_int(i), int_to_i64(car(xs).0));
                array_set_x(get(maker_st.drive_line.get().unwrap()), i64_to_int(i), int_to_i64(car(xs).1));
                (xs, i) = (cdr(xs), i64_plus(i, 1i64));
                continue;
            }
        }
    }

    pub fn drive_lines_x<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>) -> () {
        let xs = drive_sorted(get(maker_st.drive_met.get().unwrap()));
        let n = i64_plus(1i64, drive_count_of(xs, 0i64));
        set(maker_st.drive_at.get().unwrap(), make_array(i64_to_int(n), the::<i64>(0i64)));
        set(maker_st.drive_line.get().unwrap(), make_array(i64_to_int(n), the::<i64>(1i64)));
        set(maker_st.drive_count.get().unwrap(), i64_minus(n, 1i64));
        drive_fill_x(mxp, maker_st, xs, 0i64)
    }

    pub fn drive_search<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut a: i64, mut lo: i64, mut hi: i64) -> i64 {
        loop {
            if i64_gt_eq(lo, hi) {
                if i64_eq(lo, 0i64) {
                    return 1i64;
                } else {
                    return array_ref(get(maker_st.drive_line.get().unwrap()), i64_to_int(i64_minus(lo, 1i64)));
                }
            } else {
                let mid = i64_quotient(i64_plus(lo, hi), 2i64);
                if i64_lt_eq(array_ref(get(maker_st.drive_at.get().unwrap()), i64_to_int(mid)), a) {
                    lo = i64_plus(mid, 1i64);
                    continue;
                } else {
                    hi = mid;
                    continue;
                }
            }
        }
    }

    pub fn drive_placed<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, a0: Int) -> Product_11_12_13<Str, i64, i64> {
        let a = if _gt_eq(a0, maker_st.source_base.get().unwrap()) {
            mx_procedural_source_of(mxp, maker_st, a0).0
        } else {
            a0
        };
        let i = quotient(a, maker_st.load_base.get().unwrap());
        let fs = get(maker_st.drive_files.get().unwrap());
        if (_gt_eq(a, maker_st.source_base.get().unwrap()) || _gt_eq(i, drive_length(fs))) {
            Product_11_12_13(str_lit(""), 0i64, 0i64)
        } else {
            Product_11_12_13(drive_nth(fs, i), drive_search(mxp, maker_st, int_to_i64(a), 0i64, get(maker_st.drive_count.get().unwrap())), int_to_i64(remainder(a, maker_st.load_base.get().unwrap())))
        }
    }

    pub fn loc_nth(mut d: kayak_rt::value::Value, mut i: Int) -> kayak_rt::value::Value {
        loop {
            if kayak_rt::value::pair_p(d) {
                if _eq(i, int_lit(0)) {
                    return kayak_rt::value::car(d);
                } else {
                    (d, i) = (kayak_rt::value::cdr(d), _minus(i, int_lit(1)));
                    continue;
                }
            } else {
                return the::<kayak_rt::value::Value>(kayak_rt::value::Value::Nil);
            }
        }
    }

    pub fn loc_after(mut d: kayak_rt::value::Value, mut i: Int) -> kayak_rt::value::Value {
        loop {
            if (kayak_rt::value::pair_p(d) && _gt(i, int_lit(0))) {
                (d, i) = (kayak_rt::value::cdr(d), _minus(i, int_lit(1)));
                continue;
            } else {
                return d;
            }
        }
    }

    #[inline]
    pub fn loc_int(d: kayak_rt::value::Value) -> Int {
        if int_p(d) {
            kayak_rt::value::unbox::<Int>(d)
        } else {
            int_lit(0)
        }
    }

    #[inline]
    pub fn loc_string(d: kayak_rt::value::Value) -> Str {
        if string_p(d) {
            kayak_rt::value::unbox::<Str>(d)
        } else {
            str_lit("")
        }
    }

    #[inline]
    pub fn loc_nodes(d: kayak_rt::value::Value) -> List<kayak_rt::value::Value> {
        if kayak_rt::value::pair_p(d) {
            kayak_rt::heap_cons(kayak_rt::value::car(d), loc_nodes(kayak_rt::value::cdr(d)))
        } else {
            nil::<kayak_rt::value::Value>()
        }
    }

    pub fn loc_is_p(n: kayak_rt::value::Value, name: Str) -> bool {
        (_eq(loc_int(loc_nth(n, int_lit(0))), int_lit(0)) && {
            let d = loc_nth(n, int_lit(4));
            (symbol_p(d) && string_eq_p(symbol_to_string(kayak_rt::value::unbox::<Symbol>(d)), name))
        })
    }

    pub fn drive_dotted_p(mut xs: List<kayak_rt::value::Value>) -> bool {
        loop {
            if (null_p(xs) || null_p(cdr(xs)) || null_p(cdr(cdr(xs)))) {
                return false;
            } else if null_p(cdr(cdr(cdr(xs)))) {
                return (loc_is_p(car(cdr(xs)), str_lit(".")) && not(loc_is_p(car(xs), str_lit("."))));
            } else {
                xs = cdr(xs);
                continue;
            }
        }
    }

    #[inline]
    pub fn drive_before_dot(xs: List<kayak_rt::value::Value>) -> List<kayak_rt::value::Value> {
        if loc_is_p(car(xs), str_lit(".")) {
            nil::<kayak_rt::value::Value>()
        } else {
            kayak_rt::heap_cons(car(xs), drive_before_dot(cdr(xs)))
        }
    }

    pub fn drive_last(mut xs: List<kayak_rt::value::Value>) -> kayak_rt::value::Value {
        loop {
            if null_p(cdr(xs)) {
                return car(xs);
            } else {
                xs = cdr(xs);
                continue;
            }
        }
    }

    /// A located datum as Fixpt's syntax, its list's line kept.
    pub fn drive_syn<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, e: kayak_rt::value::Value) -> kayak_rt::Handle<'static, Syn> {
        let a = drive_place(mxp, maker_st, loc_string(loc_nth(e, int_lit(1))), int_to_i64(loc_int(loc_nth(e, int_lit(3)))));
        if _eq(loc_int(loc_nth(e, int_lit(0))), int_lit(1)) {
            let xs = loc_nodes(loc_after(e, int_lit(4)));
            set(maker_st.drive_met.get().unwrap(), cons(Product_11_12(a, loc_int(loc_nth(e, int_lit(2)))), get(maker_st.drive_met.get().unwrap())));
            if (not(null_p(xs)) && loc_is_p(car(xs), str_lit("#vector"))) {
                let items = drive_syns(mxp, maker_st, cdr(xs));
                vec(items, mx_datum_list(syn_datums(items)), a, a, int_lit(0))
            } else if drive_dotted_p(xs) {
                let (items, tail) = (drive_syns(mxp, maker_st, drive_before_dot(xs)), drive_syn(mxp, maker_st, drive_last(xs)));
                dotted(items, tail, mx_datum_dotted(syn_datums(items), syn_to_datum(tail)), a, a, int_lit(0))
            } else {
                let items = drive_syns(mxp, maker_st, xs);
                mk_list(items, a, a)
            }
        } else {
            atom(loc_nth(e, int_lit(4)), a, a, int_lit(0))
        }
    }

    #[inline]
    pub fn drive_syns<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, xs: List<kayak_rt::value::Value>) -> SynsA {
        if null_p(xs) {
            nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>()
        } else {
            cons(drive_syn(mxp, maker_st, car(xs)), drive_syns(mxp, maker_st, cdr(xs)))
        }
    }

    #[inline]
    pub fn loc_dotted(xs: List<kayak_rt::value::Value>, tail: kayak_rt::value::Value) -> kayak_rt::value::Value {
        if null_p(xs) {
            tail
        } else {
            the::<kayak_rt::value::Value>(kayak_rt::value::cons(car(xs), loc_dotted(cdr(xs), tail)))
        }
    }

    pub fn loc_node(k: Int, f: Str, l: i64, p: i64, d: kayak_rt::value::Value) -> kayak_rt::value::Value {
        loc_dotted(kayak_rt::heap_cons(the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(k)), kayak_rt::heap_cons(the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(f)), kayak_rt::heap_cons(the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(i64_to_int(l))), kayak_rt::heap_cons(the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(i64_to_int(p))), kayak_rt::nil())))), if _eq(k, int_lit(0)) {
            loc_dotted(kayak_rt::heap_cons(d, kayak_rt::nil()), the::<kayak_rt::value::Value>(kayak_rt::value::Value::Nil))
        } else {
            d
        })
    }

    pub fn drive_uses_in(mut us: MxExportsUses, mut a: Int, mut b: Int, mut f: Str, mut l: i64, mut p: i64) -> List<kayak_rt::value::Value> {
        loop {
            if null_p(us) {
                return nil::<kayak_rt::value::Value>();
            } else if (_eq(car(us).0, a) && _eq(car(us).1, b)) {
                return kayak_rt::heap_cons(loc_node(int_lit(1), f, l, p, mx_datum_list(kayak_rt::heap_cons(loc_node(int_lit(0), f, l, p, the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(car(us).2))), kayak_rt::heap_cons(loc_node(int_lit(0), f, l, p, the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(car(us).5))), kayak_rt::nil())))), drive_uses_in(cdr(us), a, b, f, l, p));
            } else {
                us = cdr(us);
                continue;
            }
        }
    }

    /// Syntax as a located datum, where its place says.
    pub fn drive_loc<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: kayak_rt::Handle<'static, Syn>) -> kayak_rt::value::Value {
        let w = drive_placed(mxp, maker_st, syn_start(s));
        let f = w.0;
        let l = w.1;
        let p = w.2;
        let tagcase_ = s;
        match *tagcase_ {
            made__load__2__expander::Syn::Atom(d, a, b, x) => {
                loc_node(int_lit(0), f, l, p, d)
            }
            made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                let xs = drive_locs(mxp, maker_st, items);
                let us = if (_gt_eq(len(items), int_lit(3)) && syn_symbol_p(car(items)) && string_eq_p(syn_name(car(items)), str_lit("with"))) {
                    drive_uses_in(with_uses_given(mxp, maker_st), a, b, f, l, p)
                } else {
                    nil::<kayak_rt::value::Value>()
                };
                loc_node(int_lit(1), f, l, p, mx_datum_list(if null_p(us) {
                    xs
                } else {
                    cons(car(xs), cons(car(cdr(xs)), cons(loc_node(int_lit(0), f, l, p, the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(string_to_symbol(str_lit("#:uses"))))), cons(loc_node(int_lit(1), f, l, p, mx_datum_list(us)), cdr(cdr(xs))))))
                }))
            }
            made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                loc_node(int_lit(1), f, l, p, mx_datum_list(append(drive_locs(mxp, maker_st, items), kayak_rt::cons(loc_node(int_lit(0), f, l, p, the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(string_to_symbol(str_lit("."))))), kayak_rt::cons(drive_loc(mxp, maker_st, tail), kayak_rt::nil())))))
            }
            made__load__2__expander::Syn::Vec(items, d, a, b, x) => {
                loc_node(int_lit(1), f, l, p, mx_datum_list(cons(loc_node(int_lit(0), f, l, p, the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(string_to_symbol(str_lit("#vector"))))), drive_locs(mxp, maker_st, items))))
            }
        }
    }

    #[inline]
    pub fn drive_locs<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, xs: SynsA) -> List<kayak_rt::value::Value> {
        if null_p(xs) {
            nil::<kayak_rt::value::Value>()
        } else {
            cons(drive_loc(mxp, maker_st, car(xs)), drive_locs(mxp, maker_st, cdr(xs)))
        }
    }

    pub fn drive_bare_names<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut xs: SynsA) -> Result<MxParserTypesNames, Unwind> {
        loop {
            if null_p(xs) {
                return Ok(nil::<Symbol>());
            } else if syn_symbol_p(car(xs)) {
                return Ok(cons(syn_symbol(mxp, maker_st, car(xs))?, drive_bare_names(mxp, maker_st, cdr(xs))?));
            } else {
                xs = cdr(xs);
                continue;
            }
        }
    }

    pub fn drive_heads<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut vs: SynsA) -> Result<MxParserTypesNames, Unwind> {
        loop {
            if null_p(vs) {
                return Ok(nil::<Symbol>());
            } else if (not(null_p(proper_items(car(vs)))) && syn_symbol_p(car(proper_items(car(vs))))) {
                return Ok(cons(syn_symbol(mxp, maker_st, car(proper_items(car(vs))))?, drive_heads(mxp, maker_st, cdr(vs))?));
            } else {
                vs = cdr(vs);
                continue;
            }
        }
    }

    pub fn drive_rec_names<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut bs: SynsA) -> Result<MxParserTypesNames, Unwind> {
        loop {
            if null_p(bs) {
                return Ok(nil::<Symbol>());
            } else if (not(null_p(proper_items(car(bs)))) && syn_symbol_p(car(proper_items(car(bs))))) {
                return Ok(cons(syn_symbol(mxp, maker_st, car(proper_items(car(bs))))?, drive_rec_names(mxp, maker_st, cdr(bs))?));
            } else {
                bs = cdr(bs);
                continue;
            }
        }
    }

    pub fn drive_head(s: kayak_rt::Handle<'static, Syn>) -> Str {
        let xs = proper_items(s);
        if (not(null_p(xs)) && syn_symbol_p(car(xs))) {
            syn_name(car(xs))
        } else {
            str_lit("")
        }
    }

    pub fn drive_names<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: kayak_rt::Handle<'static, Syn>) -> Result<MxParserTypesNames, Unwind> {
        let (xs, h) = (proper_items(s), drive_head(s));
        if ((string_eq_p(h, str_lit("define")) || string_eq_p(h, str_lit("define*"))) && _gt_eq(len(xs), int_lit(3)) && syn_symbol_p(nth(xs, int_lit(1)))) {
            Ok(kayak_rt::cons(syn_symbol(mxp, maker_st, nth(xs, int_lit(1)))?, kayak_rt::nil()))
        } else if string_eq_p(h, str_lit("define-rec")) {
            Ok(drive_rec_names(mxp, maker_st, cdr(xs))?)
        } else if (string_eq_p(h, str_lit("import")) && _gt_eq(len(xs), int_lit(2))) {
            Ok(drive_bare_names(mxp, maker_st, cdr(cdr(xs)))?)
        } else if (string_eq_p(h, str_lit("define-datatype")) && _gt_eq(len(xs), int_lit(3))) {
            Ok(drive_heads(mxp, maker_st, cdr(cdr(xs)))?)
        } else if (string_eq_p(h, str_lit("define-generative")) && _gt(len(xs), int_lit(3))) {
            Ok(drive_bare_names(mxp, maker_st, cdr(cdr(cdr(xs))))?)
        } else if ((string_eq_p(h, str_lit("define-syscall")) || string_eq_p(h, str_lit("define-optional-syscall"))) && _gt_eq(len(xs), int_lit(2)) && syn_symbol_p(nth(xs, int_lit(1)))) {
            Ok(kayak_rt::cons(syn_symbol(mxp, maker_st, nth(xs, int_lit(1)))?, kayak_rt::nil()))
        } else {
            Ok(nil::<Symbol>())
        }
    }

    pub fn drive_guard_names<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut ns: MxParserTypesNames, mut s: kayak_rt::Handle<'static, Syn>) -> Result<(), Unwind> {
        loop {
            if null_p(ns) {
                return Ok(());
            } else if macro_p(mxp, maker_st, car(ns)) {
                return Ok(match pfail_at(mxp, maker_st, string_append(str_lit("`"), string_append(symbol_to_string(car(ns)), str_lit("` is a macro's name, which is not defined again"))), syn_start(s), syn_end(s))? {});
            } else {
                globals_x(mxp, maker_st, kayak_rt::cons(car(ns), kayak_rt::nil()));
                ns = cdr(ns);
                continue;
            }
        }
    }

    pub fn drive_guard<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut xs: SynsA) -> Result<(), Unwind> {
        loop {
            if null_p(xs) {
                return Ok(());
            } else {
                drive_guard_names(mxp, maker_st, drive_names(mxp, maker_st, car(xs))?, car(xs))?;
                xs = cdr(xs);
                continue;
            }
        }
    }

    pub fn drive_taken<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut ns: MxParserTypesNames, mut s: kayak_rt::Handle<'static, Syn>) -> Result<(), Unwind> {
        loop {
            if null_p(ns) {
                return Ok(());
            } else if global_now_p(mxp, maker_st, car(ns)) {
                return Ok(match pfail_at(mxp, maker_st, string_append(str_lit("`"), string_append(symbol_to_string(car(ns)), str_lit("` is defined already: a macro may not take its name"))), syn_start(s), syn_end(s))? {});
            } else {
                ns = cdr(ns);
                continue;
            }
        }
    }

    pub fn drive_written<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, x: kayak_rt::Handle<'static, Syn>) -> Result<kayak_rt::Handle<'static, Syn>, Unwind> {
        let h = drive_head(x);
        if (string_eq_p(h, str_lit("include")) || string_eq_p(h, str_lit("import")) || string_eq_p(h, str_lit("define-datatype"))) {
            Ok(x)
        } else {
            Ok(top_shaped(mxp, maker_st, aliases_resolved(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_at(mxp, maker_st, a0, a1, a2)), sealed_written(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_at(mxp, maker_st, a0, a1, a2)), x)?, def_envs_given(mxp, maker_st), kayak_rt::closure0((mxp, maker_st,), |(mxp, maker_st,)| Ok((kayak_rt::closure0((mxp, maker_st,), |(mxp, maker_st,)| captor_tag(mxp, maker_st))).call())))?)?)
        }
    }

    #[inline]
    pub fn drive_written_each<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, xs: SynsA) -> Result<SynsA, Unwind> {
        if null_p(xs) {
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            Ok(cons(drive_written(mxp, maker_st, car(xs))?, drive_written_each(mxp, maker_st, cdr(xs))?))
        }
    }

    pub fn drive_checked<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, cs: SynsA) -> Result<SynsA, Unwind> {
        if null_p(cs) {
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            Ok(cons(aliases_resolved(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_at(mxp, maker_st, a0, a1, a2)), expand(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_at(mxp, maker_st, a0, a1, a2)), car(cs))?, def_envs_given(mxp, maker_st), kayak_rt::closure0((mxp, maker_st,), |(mxp, maker_st,)| Ok((kayak_rt::closure0((mxp, maker_st,), |(mxp, maker_st,)| captor_tag(mxp, maker_st))).call())))?, drive_checked(mxp, maker_st, cdr(cs))?))
        }
    }

    pub fn drive_checks<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, ns: MxParserTypesNames) -> Result<SynsA, Unwind> {
        if null_p(ns) {
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            Ok(append(drive_checked(mxp, maker_st, template_checks(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_at(mxp, maker_st, a0, a1, a2)), car(ns))?)?, drive_checks(mxp, maker_st, cdr(ns))?))
        }
    }

    #[inline]
    pub fn drive_not_yet<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: kayak_rt::Handle<'static, Syn>, what: Str) -> Result<SynsA, Unwind> {
        match pfail_at(mxp, maker_st, string_append(what, str_lit(": not yet in kayak's expander")), syn_start(s), syn_end(s))? {};
        Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
    }

    pub fn drive_begun_x<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: kayak_rt::Handle<'static, Syn>) -> () {
        form_begin_x(mxp, maker_st, s);
        made_syntax_taken_x(mxp, maker_st);
        set(maker_st.program_walk.get().unwrap(), false);
        set(maker_st.heads_on.get().unwrap(), false);
        set(maker_st.open.get().unwrap(), nil::<Symbol>());
        set(maker_st.checking.get().unwrap(), false)
    }

    pub fn drive_form<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: kayak_rt::Handle<'static, Syn>) -> Result<SynsA, Unwind> {
        drive_begun_x(mxp, maker_st, s);
        if shape_definition_p(s) {
            drive_taken(mxp, maker_st, syntax_names(mxp, maker_st, s)?, s)?;
            shape_defined_x(mxp, maker_st, s)?;
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else if defines_syntax_p(s) {
            drive_taken(mxp, maker_st, syntax_names(mxp, maker_st, s)?, s)?;
            Ok(drive_checks(mxp, maker_st, define_macro(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_at(mxp, maker_st, a0, a1, a2)), s, nil::<Product_11_12_13_14_15<Symbol, List<Symbol>, List<Symbol>, List<Product_11_12<Symbol, Symbol>>, List<Symbol>>>())?)?)
        } else if for_syntax_p(s) {
            for_syntax_x(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_at(mxp, maker_st, a0, a1, a2)), s)?;
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else if imports_syntax_p(s) {
            Ok(drive_not_yet(mxp, maker_st, s, str_lit("a file's macros, `import-with-syntax`"))?)
        } else if string_eq_p(drive_head(s), str_lit("hide")) {
            Ok(drive_forms(mxp, maker_st, cdr(proper_items(s)))?)
        } else {
            let xs = expand_top(mxp, maker_st, kayak_rt::closure3((mxp, maker_st,), |(mxp, maker_st,), a0, a1, a2| pfail_at(mxp, maker_st, a0, a1, a2)), s)?;
            let ms = made_syntax_taken_x(mxp, maker_st);
            let ws = drive_written_each(mxp, maker_st, xs)?;
            drive_taken(mxp, maker_st, ms, s)?;
            drive_guard(mxp, maker_st, ws)?;
            Ok(append(ws, drive_checks(mxp, maker_st, ms)?))
        }
    }

    pub fn drive_forms<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, xs: SynsA) -> Result<SynsA, Unwind> {
        if null_p(xs) {
            Ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::Syn>>())
        } else {
            let made = drive_form(mxp, maker_st, car(xs))?;
            Ok(append(made, drive_forms(mxp, maker_st, cdr(xs))?))
        }
    }

    pub fn drive_refused<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, m: Str, a: Int) -> Void {
        let w = drive_placed(mxp, maker_st, a);
        error(string_append(str_lit("kfx: "), string_append(w.0, string_append(str_lit(":"), string_append(int_to_string(i64_to_int(w.1)), string_append(str_lit(": "), m))))))
    }

    pub fn drive_each<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, xs: SynsA) -> Result<List<kayak_rt::value::Value>, Unwind> {
        if null_p(xs) {
            Ok(nil::<kayak_rt::value::Value>())
        } else {
            let r = {
                let prompt_tag__ = maker_st.parse_tag.get().unwrap();
                match (move || -> Result<_, Unwind> {
                    set(maker_st.drive_out.get().unwrap(), drive_form(mxp, maker_st, car(xs))?);
                    Ok(p_ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::MxParserTypesTop>>()))
                })() {
                    Ok(v_) => v_,
                    Err(u_) if u_.is(prompt_tag__) => (kayak_rt::closure1((), |(), r| {
                        r
                    })).call(prompt_tag__.payload(u_)),
                    Err(u_) => return Err(u_),
                }
            };
            let tagcase_ = r;
            match *tagcase_ {
                made__load__2__expander::Presult::PErr(m, a, b) => {
                    match drive_refused(mxp, maker_st, m, a) {};
                    Ok(nil::<kayak_rt::value::Value>())
                }
                made__load__2__expander::Presult::POk(ts) => {
                    let made = drive_locs(mxp, maker_st, get(maker_st.drive_out.get().unwrap()));
                    Ok(append(made, drive_each(mxp, maker_st, cdr(xs))?))
                }
            }
        }
    }

    pub fn drive_program_star<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, forms: List<kayak_rt::value::Value>) -> Result<List<kayak_rt::value::Value>, Unwind> {
        set(maker_st.drive_files.get().unwrap(), nil::<Str>());
        set(maker_st.drive_met.get().unwrap(), nil::<Product_11_12<Int, Int>>());
        macros_at_x(mxp, maker_st, int_lit(0));
        shapes_at_x(mxp, maker_st, int_lit(0), nil::<Product_11_12_13_14_15_16_17_18<Int, Int, Str, Str, List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>, Str, Str, bool>>());
        let xs = drive_syns(mxp, maker_st, forms);
        drive_lines_x(mxp, maker_st);
        Ok(drive_each(mxp, maker_st, xs)?)
    }

    pub fn drive_rev_onto(mut xs: List<kayak_rt::value::Value>, mut out: List<kayak_rt::value::Value>) -> List<kayak_rt::value::Value> {
        loop {
            if null_p(xs) {
                return out;
            } else {
                (xs, out) = (cdr(xs), kayak_rt::heap_cons(car(xs), out));
                continue;
            }
        }
    }

    pub fn drive_each_said<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut xs: SynsA, mut out: List<kayak_rt::value::Value>) -> Result<Product_11_12<List<kayak_rt::value::Value>, Str>, Unwind> {
        loop {
            if null_p(xs) {
                return Ok(Product_11_12(reverse(out), str_lit("")));
            } else {
                let r = {
                    let prompt_tag__ = maker_st.parse_tag.get().unwrap();
                    match (move || -> Result<_, Unwind> {
                        set(maker_st.drive_out.get().unwrap(), drive_form(mxp, maker_st, car(xs))?);
                        Ok(p_ok(nil::<kayak_rt::Handle<'static, made__load__2__expander::MxParserTypesTop>>()))
                    })() {
                        Ok(v_) => v_,
                        Err(u_) if u_.is(prompt_tag__) => (kayak_rt::closure1((), |(), r| {
                            r
                        })).call(prompt_tag__.payload(u_)),
                        Err(u_) => return Err(u_),
                    }
                };
                let tagcase_ = r;
                match *tagcase_ {
                    made__load__2__expander::Presult::PErr(m, a, b) => {
                        let w = drive_placed(mxp, maker_st, a);
                        return Ok(Product_11_12(nil::<kayak_rt::value::Value>(), string_append(str_lit("kfx: "), string_append(w.0, string_append(str_lit(":"), string_append(int_to_string(i64_to_int(w.1)), string_append(str_lit(": "), m)))))));
                    }
                    made__load__2__expander::Presult::POk(ts) => {
                        (xs, out) = (cdr(xs), drive_rev_onto(drive_locs(mxp, maker_st, get(maker_st.drive_out.get().unwrap())), out));
                        continue;
                    }
                }
            }
        }
    }

    pub fn drive_from<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, forms: List<kayak_rt::value::Value>, s: Int) -> Result<Product_11_12<List<kayak_rt::value::Value>, Str>, Unwind> {
        macros_at_x(mxp, maker_st, s);
        shapes_at_x(mxp, maker_st, s, nil::<Product_11_12_13_14_15_16_17_18<Int, Int, Str, Str, List<kayak_rt::Handle<'static, made__load__2__expander::Syn>>, Str, Str, bool>>());
        let xs = drive_syns(mxp, maker_st, forms);
        drive_lines_x(mxp, maker_st);
        Ok(drive_each_said(mxp, maker_st, xs, nil::<kayak_rt::value::Value>())?)
    }

    pub fn drive_entry_star<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, forms: List<kayak_rt::value::Value>, s: Int) -> Result<Product_11_12_13<List<kayak_rt::value::Value>, Str, Int>, Unwind> {
        let r = drive_from(mxp, maker_st, forms, s)?;
        if string_eq_p(r.1, str_lit("")) {
            let k = {
                set(maker_st.drive_states.get().unwrap(), _plus(get(maker_st.drive_states.get().unwrap()), int_lit(1)));
                get(maker_st.drive_states.get().unwrap())
            };
            macros_after_x(mxp, maker_st, k);
            shapes_after_x(mxp, maker_st, k);
            Ok(Product_11_12_13(r.0, str_lit(""), k))
        } else {
            Ok(Product_11_12_13(nil::<kayak_rt::value::Value>(), r.1, s))
        }
    }

    #[inline]
    pub fn drive_draft_star<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, forms: List<kayak_rt::value::Value>, s: Int) -> Result<Product_11_12<List<kayak_rt::value::Value>, Str>, Unwind> {
        let met = get(maker_st.drive_met.get().unwrap());
        let r = drive_from(mxp, maker_st, forms, s)?;
        set(maker_st.drive_met.get().unwrap(), met);
        Ok(r)
    }

    pub fn drive_macros_p_star<'mxp, Place_Mxp>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, s: Int) -> bool {
        let at = state_at(s, get(maker_st.by_state.get().unwrap()));
        (not(null_p(at)) && not(null_p(car(at).1)))
    }

    pub fn drive_symbols(mut s: kayak_rt::Handle<'static, Syn>, mut out: MxParserTypesNames) -> MxParserTypesNames {
        loop {
            let tagcase_ = s;
            match *tagcase_ {
                made__load__2__expander::Syn::Atom(d, a, b, x) => {
                    if (symbol_p(d) && not(mx_files_name_in_p(kayak_rt::value::unbox::<Symbol>(d), out))) {
                        return kayak_rt::heap_cons(kayak_rt::value::unbox::<Symbol>(d), out);
                    } else {
                        return out;
                    }
                }
                made__load__2__expander::Syn::MxEagerReaderTypesLst(items, d, a, b, x) => {
                    return drive_symbols_each(items, out);
                }
                made__load__2__expander::Syn::Dotted(items, tail, d, a, b, x) => {
                    (s, out) = (tail, drive_symbols_each(items, out));
                    continue;
                }
                made__load__2__expander::Syn::Vec(items, d, a, b, x) => {
                    return drive_symbols_each(items, out);
                }
            }
        }
    }

    pub fn drive_symbols_each(mut xs: SynsA, mut out: MxParserTypesNames) -> MxParserTypesNames {
        loop {
            if null_p(xs) {
                return out;
            } else {
                (xs, out) = (cdr(xs), drive_symbols(car(xs), out));
                continue;
            }
        }
    }

    pub fn drive_names_count(mut ns: MxParserTypesNames, mut k: Int) -> Int {
        loop {
            if null_p(ns) {
                return k;
            } else {
                (ns, k) = (cdr(ns), _plus(k, int_lit(1)));
                continue;
            }
        }
    }

    pub fn drive_chosen_symbols(mut ds: List<Product_11_12<kayak_rt::Handle<'static, Syn>, SeenKeys>>, mut ns: MxParserTypesNames) -> MxParserTypesNames {
        loop {
            if null_p(ds) {
                return ns;
            } else {
                (ds, ns) = (cdr(ds), drive_symbols(car(ds).0, ns));
                continue;
            }
        }
    }

    pub fn drive_define_each<'mxp, Place_Mxp>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad3MainFaceState<'mxp, Place_Mxp>, mut ds: List<Product_11_12<kayak_rt::Handle<'static, Syn>, SeenKeys>>) -> Result<(), Unwind> {
        loop {
            if null_p(ds) {
                return Ok(());
            } else {
                seen_x(mxp, maker_st, car(ds).1);
                drive_form(mxp, maker_st, car(ds).0)?;
                ds = cdr(ds);
                continue;
            }
        }
    }

